export enum IngredientType {
  FLOUR = 'flour',
  SUGAR = 'sugar',
  BUTTER = 'butter',
  YEAST = 'yeast'
}

export enum BreadType {
  SHOKUPAN = 'shokupan',
  MELONPAN = 'melonpan',
  CROISSANT = 'croissant',
  BAGUETTE = 'baguette'
}

export interface Ingredient {
  id: IngredientType;
  name: string;
  cost: number;
  stock: number;
  unit: string;
}

export interface BreadRecipe {
  id: BreadType;
  name: string;
  description: string;
  basePrice: number;
  ingredients: { [key in IngredientType]?: number }; // Amount needed per batch
  batchSize: number; // How many made per bake
  levelRequired: number;
  bakeTimeSec: number;
}

export interface BreadInventory {
  id: BreadType;
  count: number;
}

export interface DailyEvent {
  day: number;
  weather: string;
  trend: BreadType | null;
  trendReason: string;
  customerSentiment: string;
  salesModifier: number; // 1.0 is normal, 1.2 is 20% boost
}

export interface UpgradeStats {
  speed: number; // Level of speed upgrade
  batch: number; // Level of batch size upgrade
  promo: number; // Level of sales promo upgrade
}

export interface GameState {
  money: number;
  day: number;
  reputation: number; // 0-100
  shopLevel: number;
  ingredients: Record<IngredientType, number>;
  inventory: Record<BreadType, number>;
  isShopOpen: boolean;
  bakingStatus: Record<BreadType, number | null>; // number = progress (0-100), null = not baking
  upgrades: UpgradeStats;
}

