  useEffect(() => {
    if (lastSale) {
      setCustomers(prev => [...prev, { id: lastSale.id, bread: lastSale.bread }]);
    }
  }, [lastSale]);

  const handleLeave = (id: number) => {
    setCustomers(prev => prev.filter(c => c.id !== id));
  };

  return (
    <Canvas shadows camera={{ position: [0, 4, 8], fov: 40 }}>
      <color attach="background" args={['#fdf6e3']} />

      {/* Lighting */}
      <ambientLight intensity={0.7} color="#fff7ed" />
      <directionalLight 
        position={[5, 10, 5]} 
        intensity={1} 
