      <pointLight position={[-3, 2, -2]} intensity={0.5} color="#fbbf24" />

      {/* Counter */}
      <group position={[0, 0, 0]}>
        {/* Counter Top */}
        <mesh position={[0, 0.6, 1]} receiveShadow>
          <boxGeometry args={[4, 0.1, 1.5]} />
          <meshStandardMaterial color="#8b5a2b" />
        </mesh>
        {/* Counter Base */}
        <mesh position={[0, 0.3, 1]} receiveShadow>
          <boxGeometry args={[3.8, 0.6, 1.3]} />
          <meshStandardMaterial color="#a0522d" />
        </mesh>

        {/* Decorative Bread Trays */}
        <mesh position={[-1, 0.7, 1]}>
          <boxGeometry args={[0.8, 0.05, 0.6]} />
          <meshStandardMaterial color="#5c4033" />
        </mesh>
        <mesh position={[1, 0.7, 1]}>
          <boxGeometry args={[0.8, 0.05, 0.6]} />
          <meshStandardMaterial color="#5c4033" />
