}

import { BreadType, IngredientType, BreadRecipe, Ingredient } from './types';

export const INITIAL_MONEY = 100000;
export const MAX_SHOP_LEVEL = 50;

// Calculate accumulated reputation needed to reach the NEXT level
// Easy at first, harder later.
export const getReputationThreshold = (currentLevel: number): number => {
  if (currentLevel >= MAX_SHOP_LEVEL) return Infinity;

  // Base cost per level + Exponential curve for difficulty
  // Lv 1 -> 2: ~20 Rep
  // Lv 10 -> 11: ~400 Rep
  // Lv 49 -> 50: ~7000 Rep
  return Math.floor(20 * currentLevel + Math.pow(currentLevel, 2.3));
};

