import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, MAX_SHOP_LEVEL, getReputationThreshold } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    reputation: 10,
    shopLevel: 1,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1, // Start with main store
      eatIn: 0 // Start with no eat-in space
    }
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  // State for 3D Scene
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  // --- Helpers ---
  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const getAvailableRecipes = () => {
    return Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel);
  };

  // --- Actions ---
  const buyIngredient = (type: IngredientType) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const currentCost = Math.floor(item.cost * costModifier);

    if (gameState.money >= currentCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - currentCost,
        ingredients: {
          ...prev.ingredients,
          [type]: prev.ingredients[type] + 1
        }
      }));
      addLog(`仕入れ: ${item.name} を購入しました (-¥${currentCost})`);
    } else {
      addLog(`資金不足: ${item.name} が買えません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: {
          ...prev.upgrades,
          [key]: prev.upgrades[key] + 1
        }
      }));
      if (key === 'branches') {
         addLog(`事業拡大: 新しい店舗をオープンしました！ (計${gameState.upgrades.branches + 1}店舗)`);
      } else if (key === 'eatIn') {
         addLog(`設備投資: イートインスペースを拡張しました (Lv.${gameState.upgrades.eatIn + 1})`);
      } else {
         addLog(`設備投資: アップグレードを購入しました (-¥${cost})`);
      }
    }
  };

  const startBaking = (breadType: BreadType) => {
    if (gameState.bakingStatus[breadType] !== null) return;

    const recipe = RECIPES[breadType];
    const currentIngredients = gameState.ingredients;

    // Check ingredients
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        if ((currentIngredients[key] || 0) < (amount || 0)) {
            addLog(`材料不足: ${recipe.name} を焼くための ${INGREDIENTS_DATA[key].name} が足りません`);
            return;
        }
    }

    // Deduct ingredients
    const newIngredients = { ...currentIngredients };
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        newIngredients[key] -= (amount || 0);
    }

    setGameState(prev => ({
      ...prev,
      ingredients: newIngredients,
      bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
    }));
    addLog(`調理開始: ${recipe.name} を焼き始めました`);
  };

  // --- Game Loop Effects ---

  // Baking Progress
  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let changed = false;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];

          if (progress !== null) {
            const recipe = RECIPES[breadType];

            // Apply Speed Upgrade: 5% faster per level (multiply bake time by 0.95^level)
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const effectiveBakeTime = Math.max(0.1, recipe.bakeTimeSec * speedMultiplier); // Minimum 0.1s

            // Calculate increment based on effective bake time
            // Tick is 100ms (0.1s). 
            // Total ticks needed = effectiveBakeTime / 0.1 = effectiveBakeTime * 10.
            // Increment per tick = 100% / Total ticks.
            const increment = 100 / (effectiveBakeTime * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;

              // Apply Batch Upgrade: +1 bread per level
              const batchBonus = prev.upgrades.batch;
              const totalAmount = recipe.batchSize + batchBonus;

              nextInventory[breadType] += totalAmount;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成しました！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100); // 100ms tick

    return () => clearInterval(interval);
  }, []);

  // Selling Logic (When Shop is Open)
  useEffect(() => {
    if (!gameState.isShopOpen) return;

    const sellInterval = setInterval(() => {
      setGameState(prev => {
        // We try to sell for EACH store branch independently
        const numBranches = prev.upgrades.branches;

        let moneyEarned = 0;
        let reputationGained = 0;
        let saleOccurred = false;
        let lastSoldBread: BreadType | null = null;
        let eatInBonusOccurred = false;

        // Clone inventory to track changes within this tick's loop
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];

            if (availableBreads.length === 0) {
                continue; 
            }

            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];

            // Base chance
            let sellChance = 0.3 + (prev.reputation / 200); 

            // Apply Promo Upgrade: 5% additive boost per level
            const promoMultiplier = 1 + (prev.upgrades.promo * 0.05);
            sellChance *= promoMultiplier;

            // Apply Daily Event Modifiers
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) {
                    sellChance *= 1.5; 
                }
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;

                // Eat-in Logic
                // 2% chance per level to eat in, capped at 80%
                const eatInChance = Math.min(0.8, prev.upgrades.eatIn * 0.02);
                const isEatIn = Math.random() < eatInChance;

                if (isEatIn) {
                    price = Math.floor(price * 1.5); // 1.5x Multiplier for dine-in
                    eatInBonusOccurred = true;
                }

                moneyEarned += price;
                reputationGained += 0.1; 
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                saleOccurred = true;
            }
        }

        if (!saleOccurred) return prev;

        // Trigger 3D Visual Event (Just once per tick to avoid flooding, or use random sale)
        if (lastSoldBread) {
            setLastSale({ 
                id: Date.now() + Math.random(), 
                bread: lastSoldBread, 
                timestamp: Date.now() 
            });
            // Optional: Log special sale occasionally
            if (eatInBonusOccurred && Math.random() > 0.7) {
                 addLog(`店内飲食: お客さんがセットを注文しました (単価UP!)`);
            }
        }

        return {
            ...prev,
            money: prev.money + moneyEarned,
            reputation: prev.reputation + reputationGained, 
            inventory: currentInventory
        };
      });
    }, 1000); 

    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);


  // --- Phase Management ---

  const startNextDay = async () => {
    setLoadingDaily(true);
    setGameState(prev => ({ ...prev, isShopOpen: false }));

    // Generate AI Content
    const report = await generateDailyReport(gameState.day + 1, gameState.shopLevel);
    setDailyEvent(report);

    setGameState(prev => ({
        ...prev,
        day: prev.day + 1,
    }));
    setLoadingDaily(false);
  };

  const openShop = () => {
    setGameState(prev => ({ ...prev, isShopOpen: true }));
    setDailyEvent(null); 
    addLog("開店: お店をオープンしました！いらっしゃいませ！");
  };

  const closeShopEarly = () => {
    setGameState(prev => ({ ...prev, isShopOpen: false }));
    addLog("閉店: 本日の営業を終了しました。");
  };

  // Initial load
  useEffect(() => {
    if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) {
       startNextDay();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- Render Helpers ---
  const nextLevelThreshold = getReputationThreshold(gameState.shopLevel);
  const prevLevelThreshold = gameState.shopLevel === 1 ? 0 : getReputationThreshold(gameState.shopLevel - 1);
  const currentLevelProgress = Math.max(0, gameState.reputation - prevLevelThreshold);
  const levelRange = Math.max(1, nextLevelThreshold - prevLevelThreshold);
  const progressPercent = Math.min(100, (currentLevelProgress / levelRange) * 100);
  const canLevelUp = gameState.reputation >= nextLevelThreshold && gameState.shopLevel < MAX_SHOP_LEVEL;

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {/* Loading Screen */}
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <div className="animate-spin mb-4">
                <Icons.Wheat className="w-16 h-16 text-amber-500" />
            </div>
            <h2 className="text-2xl font-bold text-amber-800">朝の準備中...</h2>
            <p className="text-gray-600 mt-2">Gemini AIが今日の運勢を占っています</p>
        </div>
      )}

      {/* Daily Modal */}
      {dailyEvent && !loadingDaily && (
        <DailyModal event={dailyEvent} onClose={openShop} />
      )}

      {/* Upgrade Modal */}
      {showUpgrades && (
        <UpgradeModal 
          currentMoney={gameState.money}
          upgrades={gameState.upgrades}
          onBuy={buyUpgrade}
          onClose={() => setShowUpgrades(false)}
        />
      )}

      {/* Header */}
      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white">
                    <Icons.Store className="w-6 h-6" />
                </div>
                <div>
                    <h1 className="font-bold text-amber-900 leading-tight">AIベーカリー</h1>
                    <p className="text-xs text-amber-700">小麦の詩</p>
                </div>
            </div>

            <div className="flex items-center gap-2 md:gap-4 text-sm md:text-base">
                <div className="flex items-center gap-1 bg-amber-100 px-3 py-1 rounded-full text-amber-800">
                    <Icons.Sun className="w-4 h-4" />
                    <span className="font-bold">{gameState.day}日目</span>
                </div>
                <div className="flex items-center gap-1 bg-yellow-100 px-3 py-1 rounded-full text-yellow-800">
                    <Icons.Coins className="w-4 h-4" />
                    <span className="font-bold">¥{gameState.money.toLocaleString()}</span>
                </div>

                <button 
                  onClick={() => setShowUpgrades(true)}
                  className="hidden md:flex items-center gap-1 bg-amber-500 hover:bg-amber-600 text-white px-3 py-1 rounded-full font-bold shadow transition-colors"
                >
                  <Icons.Hammer className="w-4 h-4" />
                  設備投資
                </button>
            </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Left Column: Bakery (Baking) */}
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
                    <Icons.ChefHat className="w-5 h-5 text-amber-600" />
                    工房 (パンを焼く)
                </h2>
                <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                    {getAvailableRecipes().map(recipe => {
                      const speedBonus = Math.pow(0.95, gameState.upgrades.speed);
                      const displayTime = Math.max(0.1, recipe.bakeTimeSec * speedBonus).toFixed(1);
                      const batchBonus = gameState.upgrades.batch;

                      return (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 hover:border-amber-300 transition-colors bg-stone-50">
                            <div className="flex justify-between items-start mb-2">
                                <div>
                                    <h3 className="font-bold text-stone-800">{recipe.name}</h3>
                                    <p className="text-xs text-stone-500">{recipe.description}</p>
                                </div>
                                <div className="flex flex-col items-end gap-1">
                                    <span className="bg-white px-2 py-1 rounded text-xs font-bold border text-stone-600">
                                        {recipe.batchSize + batchBonus}個 / {displayTime}秒
                                    </span>
                                </div>
                            </div>

                            {/* Ingredients Cost */}
                            <div className="flex flex-wrap gap-2 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-xs px-2 py-1 rounded flex items-center gap-1 ${
                                        (gameState.ingredients[ing as IngredientType] || 0) < amount 
                                        ? 'bg-red-100 text-red-700' 
                                        : 'bg-green-100 text-green-700'
                                    }`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>

                            {/* Action / Progress */}
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-8 relative overflow-hidden">
                                    <div 
                                        className="bg-amber-500 h-full transition-all duration-100 ease-linear flex items-center justify-center text-white text-xs font-bold"
                                        style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}
                                    >
                                    </div>
                                    <div className="absolute inset-0 flex items-center justify-center text-xs font-bold text-stone-700 mix-blend-multiply">
                                        焼成中...
                                    </div>
                                </div>
