import React, { useRef, useState, useEffect, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Text, ContactShadows } from '@react-three/drei';
import * as THREE from 'three';
import { BreadType } from '../types';
import { RECIPES } from '../constants';

interface CustomerProps {
  id: number;
  breadType: BreadType;
  onLeave: (id: number) => void;
}

const Customer: React.FC<CustomerProps> = ({ id, breadType, onLeave }) => {
  const group = useRef<THREE.Group>(null);
  const [state, setState] = useState<'entering' | 'buying' | 'leaving'>('entering');
  const [timer, setTimer] = useState(0);

  // Random customer color
  const color = useRef(new THREE.Color().setHSL(Math.random(), 0.7, 0.6));
  const hatColor = useRef(new THREE.Color().setHSL(Math.random(), 0.5, 0.4));

  useFrame((rootState, delta) => {
    if (!group.current) return;

    // Animate walking bounce
    const time = rootState.clock.getElapsedTime();
    const bounce = Math.sin(time * 15) * 0.1;

    if (state === 'entering') {
      // Walk from left (-5) to counter (-1)
      group.current.position.x += delta * 3;
      group.current.position.y = bounce;

      if (group.current.position.x >= -1.5) {
        setState('buying');
        setTimer(0);
      }
    } else if (state === 'buying') {
      // Wait at counter
      setTimer(prev => prev + delta);
      group.current.position.y = 0; // Stop bouncing

      if (timer > 1.0) { // Buy duration
        setState('leaving');
      }
    } else if (state === 'leaving') {
      // Walk from counter (-1) to right (5)
      group.current.position.x += delta * 3;
      group.current.position.y = bounce;

      if (group.current.position.x > 5) {
        onLeave(id);
      }
    }
  });

  const recipe = RECIPES[breadType];

  return (
    <group ref={group} position={[-6, 0, 0]}>
      {/* Body */}
      <mesh position={[0, 0.6, 0]} castShadow>
        <capsuleGeometry args={[0.3, 0.6, 4, 8]} />
        <meshStandardMaterial color={color.current} />
      </mesh>
      {/* Head */}
      <mesh position={[0, 1.2, 0]} castShadow>
        <sphereGeometry args={[0.25, 16, 16]} />
        <meshStandardMaterial color="#ffdec7" />
      </mesh>
      {/* Hat */}
      <mesh position={[0, 1.45, 0]} castShadow rotation={[0,0,0]}>
        <coneGeometry args={[0.2, 0.3, 16]} />
        <meshStandardMaterial color={hatColor.current} />
      </mesh>

      {/* Bubble with Bread Name (When buying or leaving) */}
      {(state === 'buying' || state === 'leaving') && (
        <group position={[0, 2.2, 0]}>
          <Text
            fontSize={0.3}
            color="#5c4033"
            anchorX="center"
            anchorY="middle"
            outlineWidth={0.02}
            outlineColor="white"
          >
            {recipe.name.substring(0, 4)}..
          </Text>
          <Text
            position={[0, -0.35, 0]}
            fontSize={0.25}
            color="#d97706"
            anchorX="center"
            anchorY="middle"
            outlineWidth={0.02}
            outlineColor="white"
          >
            +¥{recipe.basePrice}
          </Text>
        </group>
      )}
    </group>
  );
};

// --- Bread Components ---

const BreadMesh: React.FC<{ type: BreadType }> = ({ type }) => {
  const color = useMemo(() => {
    switch(type) {
      case BreadType.SHOKUPAN: return '#f5deb3'; // Wheat
      case BreadType.ANPAN: return '#8b4513'; // SaddleBrown
      case BreadType.MELONPAN: return '#98fb98'; // PaleGreen (or cookie color)
      case BreadType.BAGUETTE: return '#cd853f'; // Peru
      case BreadType.CROISSANT: return '#daa520'; // GoldenRod
      case BreadType.CURRYPAN: return '#d2691e'; // Chocolate
      default: return '#deb887'; // BurlyWood
    }
  }, [type]);

  const geometry = useMemo(() => {
    switch(type) {
      case BreadType.SHOKUPAN: 
        return <boxGeometry args={[0.3, 0.3, 0.3]} />;
      case BreadType.BAGUETTE:
        return <capsuleGeometry args={[0.08, 0.4, 4, 8]} />;
      case BreadType.BAGEL:
      case BreadType.CROISSANT:
      case BreadType.PRETZEL:
        return <torusGeometry args={[0.12, 0.06, 8, 16]} />;
      default:
        return <sphereGeometry args={[0.15, 16, 16]} />;
    }
  }, [type]);

  // Adjust rotation for some shapes
  const rotation: [number, number, number] = 
    (type === BreadType.BAGUETTE || type === BreadType.EPI) ? [0, 0, Math.PI / 2] : 
    (type === BreadType.BAGEL || type === BreadType.CROISSANT) ? [Math.PI / 2, 0, 0] : [0, 0, 0];

  const yOffset = type === BreadType.BAGUETTE ? 0.08 : 0.15;

  return (
    <mesh castShadow receiveShadow rotation={rotation} position={[0, yOffset, 0]}>
      {geometry}
      <meshStandardMaterial color={color} roughness={0.7} />
    </mesh>
  );
};

interface SceneProps {
  lastSale: { id: number; bread: BreadType; timestamp: number } | null;
  inventory?: Record<BreadType, number>;
}

export const Bakery3DScene: React.FC<SceneProps> = ({ lastSale, inventory }) => {
  const [customers, setCustomers] = useState<{ id: number; bread: BreadType }[]>([]);

  // Effect to spawn customer on sale
  useEffect(() => {
    if (lastSale) {
      setCustomers(prev => [...prev, { id: lastSale.id, bread: lastSale.bread }]);
    }
  }, [lastSale]);

  const handleLeave = (id: number) => {
    setCustomers(prev => prev.filter(c => c.id !== id));
  };

  // Prepare bread display lists
  // We will distribute available breads between counter trays and a background shelf
  const availableBreads = useMemo(() => {
    if (!inventory) return [];
    // Fixing type issue where count might be inferred as unknown in some environments
    return (Object.entries(inventory) as [string, number][])
      .filter(([_, count]) => count > 0)
      .map(([type]) => type as BreadType);
  }, [inventory]);

  // Simple distribution logic: first 4 types on counter, rest on shelf
  const counterBreads = availableBreads.slice(0, 4);
  const shelfBreads = availableBreads.slice(4, 12);

  return (
    <Canvas shadows camera={{ position: [0, 5, 8], fov: 45 }}>
      <color attach="background" args={['#fdf6e3']} />

      {/* Lighting */}
      <ambientLight intensity={0.6} color="#fff7ed" />
      <directionalLight 
        position={[5, 10, 5]} 
        intensity={1.2} 
        castShadow 
        shadow-mapSize={[1024, 1024]} 
      />
      <pointLight position={[-3, 2, -2]} intensity={0.5} color="#fbbf24" />

      {/* --- Shop Furniture --- */}

      {/* Main Counter */}
      <group position={[0, 0, 1]}>
        {/* Counter Top */}
        <mesh position={[0, 0.6, 0]} receiveShadow>
          <boxGeometry args={[4.5, 0.1, 1.2]} />
          <meshStandardMaterial color="#8b5a2b" />
        </mesh>
        {/* Counter Base */}
        <mesh position={[0, 0.3, 0]} receiveShadow>
          <boxGeometry args={[4.3, 0.6, 1.0]} />
          <meshStandardMaterial color="#a0522d" />
        </mesh>

        {/* Trays on Counter */}
        {/* Left Tray */}
        <group position={[-1.2, 0.65, 0.1]}>
          <mesh receiveShadow>
            <boxGeometry args={[1.5, 0.05, 0.8]} />
            <meshStandardMaterial color="#3e2723" />
          </mesh>
          {/* Breads on Left Tray */}
          {/* Casting inventory access to number to fix "unknown" comparison error */}
          {counterBreads[0] && inventory && (inventory[counterBreads[0]] as number) > 0 && (
            <group position={[-0.4, 0, 0]}>
              <BreadMesh type={counterBreads[0]} />
              {(inventory[counterBreads[0]] as number) > 3 && <group position={[0.4, 0, 0]}><BreadMesh type={counterBreads[0]} /></group>}
              {(inventory[counterBreads[0]] as number) > 6 && <group position={[0.2, 0.15, 0.1]}><BreadMesh type={counterBreads[0]} /></group>}
            </group>
          )}
           {counterBreads[1] && inventory && (inventory[counterBreads[1]] as number) > 0 && (
            <group position={[0.4, 0, 0]}>
              <BreadMesh type={counterBreads[1]} />
              {(inventory[counterBreads[1]] as number) > 3 && <group position={[0.4, 0, 0]}><BreadMesh type={counterBreads[1]} /></group>}
            </group>
          )}
        </group>

        {/* Right Tray */}
        <group position={[1.2, 0.65, 0.1]}>
          <mesh receiveShadow>
            <boxGeometry args={[1.5, 0.05, 0.8]} />
            <meshStandardMaterial color="#3e2723" />
          </mesh>
          {/* Breads on Right Tray */}
          {/* Casting inventory access to number to fix "unknown" comparison error */}
          {counterBreads[2] && inventory && (inventory[counterBreads[2]] as number) > 0 && (
            <group position={[-0.4, 0, 0]}>
              <BreadMesh type={counterBreads[2]} />
               {(inventory[counterBreads[2]] as number) > 3 && <group position={[0.4, 0, 0]}><BreadMesh type={counterBreads[2]} /></group>}
            </group>
          )}
          {counterBreads[3] && inventory && (inventory[counterBreads[3]] as number) > 0 && (
            <group position={[0.4, 0, 0]}>
              <BreadMesh type={counterBreads[3]} />
            </group>
          )}
        </group>
      </group>

      {/* Back Display Shelf */}
      <group position={[0, 0, -2]}>
        {/* Shelf Structure */}
        <mesh position={[0, 1.5, 0]} castShadow receiveShadow>
          <boxGeometry args={[5, 3, 0.5]} />
          <meshStandardMaterial color="#d2b48c" />
        </mesh>
        {/* Shelf Levels */}
        <mesh position={[0, 1, 0.3]} receiveShadow>
           <boxGeometry args={[4.8, 0.1, 0.6]} />
           <meshStandardMaterial color="#8b4513" />
        </mesh>
        <mesh position={[0, 2, 0.3]} receiveShadow>
           <boxGeometry args={[4.8, 0.1, 0.6]} />
           <meshStandardMaterial color="#8b4513" />
        </mesh>

        {/* Breads on Shelf */}
        {shelfBreads.map((bread, i) => {
            // Casting inventory access to number to fix "unknown" comparison error
            if (!inventory || (inventory[bread] as number) <= 0) return null;
            const row = Math.floor(i / 4); // 0 or 1
            const col = i % 4;
            const x = -1.5 + col * 1.0;
            const y = row === 0 ? 2.1 : 1.1; // Top shelf first?
            return (
              <group key={bread} position={[x, y, 0.3]}>
                <BreadMesh type={bread} />
                {/* Stack effect */}
                <group position={[0.1, 0, -0.1]}><BreadMesh type={bread} /></group>
              </group>
            );
        })}
      </group>

      {/* Shop Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[20, 10]} />
        <meshStandardMaterial color="#fef3c7" />
      </mesh>

      {/* Customers */}
      {customers.map(c => (
        <Customer key={c.id} id={c.id} breadType={c.bread} onLeave={handleLeave} />
      ))}

      <ContactShadows opacity={0.4} scale={15} blur={2.5} far={4} color="#000000" />
    </Canvas>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { DailyEvent, BreadType } from '../types';

// Fallback data in case API key is missing or fails
const FALLBACK_EVENT: DailyEvent = {
  day: 1,
  weather: '晴れ',
  trend: BreadType.SHOKUPAN,
  trendReason: 'テレビで食パン特集が放送されたため、需要が高まっています。',
  customerSentiment: '「いい匂いがする！」とお客さんは楽しそうです。',
  salesModifier: 1.2,
  costModifier: 1.0
};

export const generateDailyReport = async (day: number, currentLevel: number): Promise<DailyEvent> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.warn("API Key not found, using fallback event.");
    return { ...FALLBACK_EVENT, day };
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    // Choose a random bread type to be trending potentially, passed as context
    const breadTypes = Object.values(BreadType);

    const prompt = `
      あなたはパン屋さん経営シミュレーションゲームの「ゲームマスターAI」です。
      現在はゲームの${day}日目です。店舗レベルは${currentLevel}です。
      今日1日の「天気」「流行っているパン」「その理由」「客の様子」「売上補正倍率」「仕入れ価格変動倍率」を生成してください。

      パンの種類リスト: ${breadTypes.join(', ')}

      以下のJSON形式で出力してください。
      売上補正倍率(salesModifier)は、0.8 (不況/悪天候) から 1.5 (大ブーム/快晴) の間で設定してください。
      仕入れ価格変動倍率(costModifier)は、0.7 (豊作/円高) から 1.6 (不作/円安) の間で設定してください。天候が悪いと物流が遅れて高くなるなどの要素も考慮してください。
      trendはパンの種類リストから1つ選んでください。特になければ null でも構いません。
    `;

    // Always use gemini-3-flash-preview for general text tasks like game event generation
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weather: { type: Type.STRING, description: "今日の天気 (例: 快晴、大雨、曇り)" },
            trend: { type: Type.STRING, description: "今日流行しているパンのID (enum値)。ない場合はnull" },
            trendReason: { type: Type.STRING, description: "なぜそのパンが流行っているか、または今日の街の様子" },
            customerSentiment: { type: Type.STRING, description: "今日のお客さんの雰囲気や会話" },
            salesModifier: { type: Type.NUMBER, description: "売上の倍率 (0.8 ~ 1.5)" },
            costModifier: { type: Type.NUMBER, description: "仕入れ価格の倍率 (0.7 ~ 1.6)" }
          },
          required: ["weather", "trendReason", "customerSentiment", "salesModifier", "costModifier"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");

    // Validate trend is valid enum or null
    let validTrend: BreadType | null = null;
    if (data.trend && Object.values(BreadType).includes(data.trend as BreadType)) {
      validTrend = data.trend as BreadType;
    }

    return {
      day: day,
      weather: data.weather || "晴れ",
      trend: validTrend,
      trendReason: data.trendReason || "今日は穏やかな一日です。",
      customerSentiment: data.customerSentiment || "お客さんは期待しています。",
      salesModifier: data.salesModifier || 1.0,
      costModifier: data.costModifier || 1.0
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { ...FALLBACK_EVENT, day };
  }
};

import React, { useRef, useState, useEffect, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Text, ContactShadows } from '@react-three/drei';
import * as THREE from 'three';
import { BreadType } from '../types';
import { RECIPES } from '../constants';

interface CustomerProps {
  id: number;
  breadType: BreadType;
  onLeave: (id: number) => void;
}

const Customer: React.FC<CustomerProps> = ({ id, breadType, onLeave }) => {
  const group = useRef<THREE.Group>(null);
  const [state, setState] = useState<'entering' | 'buying' | 'leaving'>('entering');
  const [timer, setTimer] = useState(0);

  const color = useRef(new THREE.Color().setHSL(Math.random(), 0.7, 0.6));
  const hatColor = useRef(new THREE.Color().setHSL(Math.random(), 0.5, 0.4));

  useFrame((rootState, delta) => {
    if (!group.current) return;
    const time = rootState.clock.getElapsedTime();
    const bounce = Math.sin(time * 15) * 0.1;

    if (state === 'entering') {
      group.current.position.x += delta * 3;
      group.current.position.y = bounce;
      if (group.current.position.x >= -1.5) {
        setState('buying');
        setTimer(0);
      }
    } else if (state === 'buying') {
      setTimer(prev => prev + delta);
      group.current.position.y = 0;
      if (timer > 1.0) {
        setState('leaving');
      }
    } else if (state === 'leaving') {
      group.current.position.x += delta * 3;
      group.current.position.y = bounce;
      if (group.current.position.x > 5) {
        onLeave(id);
      }
    }
  });

  const recipe = RECIPES[breadType];

  return (
    <group ref={group} position={[-6, 0, 0]}>
      <mesh position={[0, 0.6, 0]} castShadow>
        <capsuleGeometry args={[0.3, 0.6, 4, 8]} />
        <meshStandardMaterial color={color.current} />
      </mesh>
      <mesh position={[0, 1.2, 0]} castShadow>
        <sphereGeometry args={[0.25, 16, 16]} />
        <meshStandardMaterial color="#ffdec7" />
      </mesh>
      {(state === 'buying' || state === 'leaving') && (
        <group position={[0, 2.2, 0]}>
          <Text fontSize={0.3} color="#5c4033" anchorX="center" anchorY="middle" outlineWidth={0.02} outlineColor="white">
            {recipe.name.substring(0, 4)}..
          </Text>
        </group>
      )}
    </group>
  );
};

