import { GoogleGenAI, Type } from "@google/genai";
import { DailyEvent, BreadType, DailyMission } from '../types';

const FALLBACK_EVENT: DailyEvent = {
  day: 1,
  weather: '晴れ',
  trend: BreadType.SHOKUPAN,
  trendReason: 'テレビで食パン特集が放送されたため、需要が高まっています。',
  customerSentiment: '「いい匂いがする！」とお客さんは楽しそうです。',
  salesModifier: 1.2,
  costModifier: 1.0,
  missions: [
    { id: 'm1', description: '食パンを10個販売する', targetValue: 10, currentValue: 0, type: 'sell_bread', targetId: BreadType.SHOKUPAN, isCleared: false },
    { id: 'm2', description: 'パンを合計30個焼く', targetValue: 30, currentValue: 0, type: 'bake_bread', isCleared: false },
    { id: 'm3', description: '本日の売上10,000円達成', targetValue: 10000, currentValue: 0, type: 'earn_money', isCleared: false }
  ]
};

export const generateDailyReport = async (day: number, currentLevel: number): Promise<DailyEvent> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    return { ...FALLBACK_EVENT, day };
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    const breadTypes = Object.values(BreadType);

    const prompt = `
      あなたはパン屋さん経営シミュレーションゲームの「ゲームマスターAI」です。
      ${day}日目、店舗Lv.${currentLevel}の状況を生成してください。

      パンの種類リスト: ${breadTypes.join(', ')}

      以下のJSON形式で出力してください。
      売上補正倍率(salesModifier): 0.8 ~ 1.5
      仕入れ価格変動倍率(costModifier): 0.7 ~ 1.6

      また、今日挑戦する3つの「デイリーミッション」を生成してください。
      ミッションタイプ: sell_bread, bake_bread, earn_money, buy_ingredient
      targetIdにはパンIDや材料IDを入れてください。
      targetValueは店舗レベルに応じて、少し頑張れば達成できる値（例: Lv.1なら販売数10、Lv.10なら50など）にしてください。
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weather: { type: Type.STRING },
            trend: { type: Type.STRING },
            trendReason: { type: Type.STRING },
            customerSentiment: { type: Type.STRING },
            salesModifier: { type: Type.NUMBER },
            costModifier: { type: Type.NUMBER },
            missions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  description: { type: Type.STRING },
                  targetValue: { type: Type.NUMBER },
                  type: { type: Type.STRING },
                  targetId: { type: Type.STRING }
                }
              }
            }
          },
          required: ["weather", "trendReason", "customerSentiment", "salesModifier", "costModifier", "missions"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");

    let validTrend: BreadType | null = null;
    if (data.trend && Object.values(BreadType).includes(data.trend as BreadType)) {
      validTrend = data.trend as BreadType;
    }

    const missions: DailyMission[] = (data.missions || []).map((m: any, i: number) => ({
      id: `mission-${day}-${i}`,
      description: m.description,
      targetValue: m.targetValue,
      currentValue: 0,
      type: m.type,
      targetId: m.targetId,
      isCleared: false
    }));

    return {
      day: day,
      weather: data.weather || "晴れ",
      trend: validTrend,
      trendReason: data.trendReason || "今日は穏やかな一日です。",
      customerSentiment: data.customerSentiment || "お客さんは期待しています。",
      salesModifier: data.salesModifier || 1.0,
      costModifier: data.costModifier || 1.0,
      missions: missions.length === 3 ? missions : FALLBACK_EVENT.missions
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { ...FALLBACK_EVENT, day };
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, MAX_SHOP_LEVEL, getLevelUpThreshold } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const checkMissions = (type: DailyMission['type'], targetId: string | undefined, increment: number) => {
    setGameState(prev => {
      let missionsChanged = false;
      const nextMissions = prev.currentMissions.map(mission => {
        if (mission.isCleared) return mission;

        let shouldIncrement = false;
        if (mission.type === type) {
          if (!mission.targetId || mission.targetId === targetId) {
            shouldIncrement = true;
          }
        }

        if (shouldIncrement) {
          const nextVal = mission.currentValue + increment;
          const isNowCleared = nextVal >= mission.targetValue;
          if (isNowCleared) {
            addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
            missionsChanged = true;
          }
          return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
        }
        return mission;
      });

      if (!missionsChanged && nextMissions === prev.currentMissions) return prev;

      let extraMoney = 0;
      nextMissions.forEach((m, i) => {
        if (m.isCleared && !prev.currentMissions[i].isCleared) {
          extraMoney += 50000;
        }
      });

      // All cleared check
      let bonusMoney = 0;
      let allClaimed = prev.allMissionsBonusClaimed;
      if (!allClaimed && nextMissions.every(m => m.isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        bonusMoney = 150000; // Total reward will be 50k*3 + 150k = 300k
        allClaimed = true;
      }

      return {
        ...prev,
        currentMissions: nextMissions,
        money: prev.money + extraMoney + bonusMoney,
        allMissionsBonusClaimed: allClaimed
      };
    });
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - totalCost,
        ingredients: {
          ...prev.ingredients,
          [type]: prev.ingredients[type] + amount
        }
      }));
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      checkMissions('buy_ingredient', type, amount);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: {
          ...prev.upgrades,
          [key]: prev.upgrades[key] + 1
        }
      }));
      addLog(`設備投資: アップグレードを購入しました (-¥${cost})`);
    }
  };

  const startBaking = (breadType: BreadType) => {
    if (gameState.bakingStatus[breadType] !== null) return;
    const recipe = RECIPES[breadType];
    const currentIngredients = gameState.ingredients;

    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        if ((currentIngredients[key] || 0) < (amount || 0)) {
            addLog(`材料不足: ${recipe.name} を焼くための ${INGREDIENTS_DATA[key].name} が足りません`);
            return;
        }
    }

    const newIngredients = { ...currentIngredients };
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        newIngredients[key] -= (amount || 0);
    }

    setGameState(prev => ({
      ...prev,
      ingredients: newIngredients,
      bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
    }));
    addLog(`調理開始: ${recipe.name} を焼き始めました`);
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let changed = false;
        let bakedCount = 0;
        let bakedType: BreadType | null = null;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const effectiveBakeTime = Math.max(0.1, recipe.bakeTimeSec * speedMultiplier);
            const increment = 100 / (effectiveBakeTime * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成しました！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (bakedCount > 0) {
          setTimeout(() => checkMissions('bake_bread', bakedType!, bakedCount), 0);
        }

        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      let moneyEarnedSession = 0;
      let soldBreads: {type: BreadType, count: number}[] = [];

      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let saleOccurred = false;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];
            if (availableBreads.length === 0) continue; 

            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = 0.3 + (prev.reputation / 200); 
            sellChance *= (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                const isEatIn = Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02);
                if (isEatIn) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                saleOccurred = true;

                const existing = soldBreads.find(sb => sb.type === breadToSell);
                if (existing) existing.count++;
                else soldBreads.push({type: breadToSell, count: 1});
            }
        }

        if (!saleOccurred) return prev;
        moneyEarnedSession = moneyEarned;
        if (lastSoldBread) {
            setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        }
        return {
            ...prev,
            money: prev.money + moneyEarned,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory
        };
      });

      if (moneyEarnedSession > 0) {
        checkMissions('earn_money', undefined, moneyEarnedSession);
        soldBreads.forEach(sb => checkMissions('sell_bread', sb.type, sb.count));
      }
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => {
    setGameState(prev => ({ ...prev, isShopOpen: true }));
    setDailyEvent(null);
    addLog("開店: お店をオープンしました！");
  };
  const closeShopEarly = () => {
    setGameState(prev => ({ ...prev, isShopOpen: false }));
    addLog("閉店: 本日の営業を終了しました。");
  };

  useEffect(() => {
    if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1);
  }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800">朝の準備中...</h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white"><Icons.Store className="w-6 h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight">AIベーカリー</h1></div>
            </div>
            <div className="flex items-center gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-sm font-bold">{gameState.day}日目</div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1 rounded-full text-sm font-bold shadow"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {getAvailableRecipes().map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50">
                            <h3 className="font-bold text-stone-800 mb-2">{recipe.name}</h3>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden"><div className="bg-amber-500 h-full transition-all duration-100" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm">焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">
                                    {cam.name}
                                </span>
                                {gameState.isShopOpen && (
                                    <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded">
                                        <div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div>
                                        <span className="text-white text-[7px] font-bold font-mono">REC</span>
                                    </div>
                                )}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene 
                                    lastSale={lastSale} 
                                    inventory={gameState.inventory} 
                                    eatInLevel={gameState.upgrades.eatIn}
                                    cameraPosition={cam.pos}
                                    cameraFov={cam.fov}
                                />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">
                                    No Signal / {cam.name}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase">
                    <span>AI-CCTV v3.5</span>
                    <span className="animate-pulse">{gameState.isShopOpen ? "Online" : "Standby"}</span>
                </div>
            </section>

            {/* Daily Missions Board */}
            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm">
                    DAILY MISSIONS
                </div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
                    <Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 今日の目標
                </h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>
                                    {m.description}
                                </span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} 
                                    style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500 uppercase">
                                <span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span>
                                <span>{m.isCleared ? "Completed" : "In Progress"}</span>
                            </div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && (
                        <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg">
                           🎉 全ミッション達成ボーナス獲得！
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {getAvailableRecipes().map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>

                <div className="mt-4 pt-4 border-t border-amber-100">
                    <h3 className="text-sm font-bold text-amber-800 mb-2">店舗レベル: {gameState.shopLevel}</h3>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    <div className="flex justify-between items-center">
                        <span className="text-[10px] text-gray-500">実績: {gameState.levelProgressSales}個</span>
                        {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                            <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="py-1 px-3 bg-orange-500 text-white text-[10px] font-bold rounded-lg animate-bounce">レベルUP可能</button>
                        )}
                    </div>
                </div>

                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2">次の日へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>

            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1">> {log}</div>)}
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー (仕入れ)</h2>
                <div className="mb-3 bg-amber-50 p-2 rounded text-[10px] text-amber-800 flex justify-between items-center border border-amber-100">
                   <span>本日の価格相場:</span>
                   <span className="font-bold">{(dailyEvent?.costModifier || 1.0).toFixed(2)}倍</span>
                </div>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const costModifier = dailyEvent?.costModifier || 1.0;
                        const unitCost = Math.floor(item.cost * costModifier);
                        const isExpensive = costModifier > 1.0;
                        const isCheap = costModifier < 1.0;
                        const purchaseOptions = [1, 10, 50];

                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl hover:bg-stone-50 transition-colors">
                                <div className="flex items-center justify-between mb-3">
                                    <div>
                                        <div className="font-bold text-stone-700 text-sm">{item.name}</div>
                                        <div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div>
                                    </div>
                                    <div className={`text-[10px] font-bold px-2 py-0.5 rounded ${isExpensive ? 'text-red-500' : isCheap ? 'text-green-600' : 'text-stone-400'}`}>
                                        単価 ¥{unitCost}
                                    </div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {purchaseOptions.map(amount => {
                                        const totalCost = unitCost * amount;
                                        const canAfford = gameState.money >= totalCost;
                                        return (
                                            <button 
                                                key={amount}
                                                onClick={() => buyIngredient(item.id, amount)}
                                                disabled={!canAfford}
                                                className={`py-2 px-1 rounded-lg text-[10px] font-bold flex flex-col items-center transition-all border
                                                    ${canAfford 
                                                        ? 'bg-white text-stone-700 hover:bg-amber-50 border-stone-200 active:scale-95' 
                                                        : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}
                                                `}
                                            >
                                                <span className="opacity-70">x{amount}</span>
                                                <span>¥{totalCost.toLocaleString()}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, MAX_SHOP_LEVEL, getLevelUpThreshold } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const checkMissions = (type: DailyMission['type'], targetId: string | undefined, increment: number) => {
    setGameState(prev => {
      let missionsChanged = false;
      const nextMissions = prev.currentMissions.map(mission => {
        if (mission.isCleared) return mission;

        let shouldIncrement = false;
        if (mission.type === type) {
          if (!mission.targetId || mission.targetId === targetId) {
            shouldIncrement = true;
          }
        }

        if (shouldIncrement) {
          const nextVal = mission.currentValue + increment;
          const isNowCleared = nextVal >= mission.targetValue;
          if (isNowCleared) {
            addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
            missionsChanged = true;
          }
          return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
        }
        return mission;
      });

      if (!missionsChanged && nextMissions === prev.currentMissions) return prev;

      let extraMoney = 0;
      nextMissions.forEach((m, i) => {
        if (m.isCleared && !prev.currentMissions[i].isCleared) {
          extraMoney += 50000;
        }
      });

      // All cleared check
      let bonusMoney = 0;
      let allClaimed = prev.allMissionsBonusClaimed;
      if (!allClaimed && nextMissions.every(m => m.isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        bonusMoney = 150000; // Total reward will be 50k*3 + 150k = 300k
        allClaimed = true;
      }

      return {
        ...prev,
        currentMissions: nextMissions,
        money: prev.money + extraMoney + bonusMoney,
        allMissionsBonusClaimed: allClaimed
      };
    });
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - totalCost,
        ingredients: {
          ...prev.ingredients,
          [type]: prev.ingredients[type] + amount
        }
      }));
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      checkMissions('buy_ingredient', type, amount);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: {
          ...prev.upgrades,
          [key]: prev.upgrades[key] + 1
        }
      }));
      addLog(`設備投資: アップグレードを購入しました (-¥${cost})`);
    }
  };

  const startBaking = (breadType: BreadType) => {
    if (gameState.bakingStatus[breadType] !== null) return;
    const recipe = RECIPES[breadType];
    const currentIngredients = gameState.ingredients;

    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        if ((currentIngredients[key] || 0) < (amount || 0)) {
            addLog(`材料不足: ${recipe.name} を焼くための ${INGREDIENTS_DATA[key].name} が足りません`);
            return;
        }
    }

    const newIngredients = { ...currentIngredients };
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        newIngredients[key] -= (amount || 0);
    }

    setGameState(prev => ({
      ...prev,
      ingredients: newIngredients,
      bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
    }));
    addLog(`調理開始: ${recipe.name} を焼き始めました`);
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let changed = false;
        let bakedCount = 0;
        let bakedType: BreadType | null = null;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const effectiveBakeTime = Math.max(0.1, recipe.bakeTimeSec * speedMultiplier);
            const increment = 100 / (effectiveBakeTime * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成しました！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (bakedCount > 0) {
          setTimeout(() => checkMissions('bake_bread', bakedType!, bakedCount), 0);
        }

        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      let moneyEarnedSession = 0;
      let soldBreads: {type: BreadType, count: number}[] = [];

      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let saleOccurred = false;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];
            if (availableBreads.length === 0) continue; 

            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = 0.3 + (prev.reputation / 200); 
            sellChance *= (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                const isEatIn = Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02);
                if (isEatIn) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                saleOccurred = true;

                const existing = soldBreads.find(sb => sb.type === breadToSell);
                if (existing) existing.count++;
                else soldBreads.push({type: breadToSell, count: 1});
            }
        }

        if (!saleOccurred) return prev;
        moneyEarnedSession = moneyEarned;
        if (lastSoldBread) {
            setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        }
        return {
            ...prev,
            money: prev.money + moneyEarned,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory
        };
      });

      if (moneyEarnedSession > 0) {
        checkMissions('earn_money', undefined, moneyEarnedSession);
        soldBreads.forEach(sb => checkMissions('sell_bread', sb.type, sb.count));
      }
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => {
    setGameState(prev => ({ ...prev, isShopOpen: true }));
    setDailyEvent(null);
    addLog("開店: お店をオープンしました！");
  };
  const closeShopEarly = () => {
    setGameState(prev => ({ ...prev, isShopOpen: false }));
    addLog("閉店: 本日の営業を終了しました。");
  };

  useEffect(() => {
    if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1);
  }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);

  // Fix: Added missing getAvailableRecipes function to filter RECIPES by shop level
  const getAvailableRecipes = () => {
    return Object.values(RECIPES).filter(recipe => recipe.levelRequired <= gameState.shopLevel);
  };

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800">朝の準備中...</h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white"><Icons.Store className="w-6 h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight">AIベーカリー</h1></div>
            </div>
            <div className="flex items-center gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-sm font-bold">{gameState.day}日目</div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1 rounded-full text-sm font-bold shadow"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {getAvailableRecipes().map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50">
                            <h3 className="font-bold text-stone-800 mb-2">{recipe.name}</h3>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden"><div className="bg-amber-500 h-full transition-all duration-100" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm">焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">
                                    {cam.name}
                                </span>
                                {gameState.isShopOpen && (
                                    <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded">
                                        <div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div>
                                        <span className="text-white text-[7px] font-bold font-mono">REC</span>
                                    </div>
                                )}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene 
                                    lastSale={lastSale} 
                                    inventory={gameState.inventory} 
                                    eatInLevel={gameState.upgrades.eatIn}
                                    cameraPosition={cam.pos}
                                    cameraFov={cam.fov}
                                />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">
                                    No Signal / {cam.name}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase">
                    <span>AI-CCTV v3.5</span>
                    <span className="animate-pulse">{gameState.isShopOpen ? "Online" : "Standby"}</span>
                </div>
            </section>

            {/* Daily Missions Board */}
            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm">
                    DAILY MISSIONS
                </div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
                    <Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 今日の目標
                </h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>
                                    {m.description}
                                </span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} 
                                    style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500 uppercase">
                                <span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span>
                                <span>{m.isCleared ? "Completed" : "In Progress"}</span>
                            </div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && (
                        <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg">
                           🎉 全ミッション達成ボーナス獲得！
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {getAvailableRecipes().map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>

                <div className="mt-4 pt-4 border-t border-amber-100">
                    <h3 className="text-sm font-bold text-amber-800 mb-2">店舗レベル: {gameState.shopLevel}</h3>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    <div className="flex justify-between items-center">
                        <span className="text-[10px] text-gray-500">実績: {gameState.levelProgressSales}個</span>
                        {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                            <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="py-1 px-3 bg-orange-500 text-white text-[10px] font-bold rounded-lg animate-bounce">レベルUP可能</button>
                        )}
                    </div>
                </div>

                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2">次の日へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>

            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1">> {log}</div>)}
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー (仕入れ)</h2>
                <div className="mb-3 bg-amber-50 p-2 rounded text-[10px] text-amber-800 flex justify-between items-center border border-amber-100">
                   <span>本日の価格相場:</span>
                   <span className="font-bold">{(dailyEvent?.costModifier || 1.0).toFixed(2)}倍</span>
                </div>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const costModifier = dailyEvent?.costModifier || 1.0;
                        const unitCost = Math.floor(item.cost * costModifier);
                        const isExpensive = costModifier > 1.0;
                        const isCheap = costModifier < 1.0;
                        const purchaseOptions = [1, 10, 50];

                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl hover:bg-stone-50 transition-colors">
                                <div className="flex items-center justify-between mb-3">
                                    <div>
                                        <div className="font-bold text-stone-700 text-sm">{item.name}</div>
                                        <div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div>
                                    </div>
                                    <div className={`text-[10px] font-bold px-2 py-0.5 rounded ${isExpensive ? 'text-red-500' : isCheap ? 'text-green-600' : 'text-stone-400'}`}>
                                        単価 ¥{unitCost}
                                    </div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {purchaseOptions.map(amount => {
                                        const totalCost = unitCost * amount;
                                        const canAfford = gameState.money >= totalCost;
                                        return (
                                            <button 
                                                key={amount}
                                                onClick={() => buyIngredient(item.id, amount)}
                                                disabled={!canAfford}
                                                className={`py-2 px-1 rounded-lg text-[10px] font-bold flex flex-col items-center transition-all border
                                                    ${canAfford 
                                                        ? 'bg-white text-stone-700 hover:bg-amber-50 border-stone-200 active:scale-95' 
                                                        : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}
                                                `}
                                            >
                                                <span className="opacity-70">x{amount}</span>
                                                <span>¥{totalCost.toLocaleString()}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, MAX_SHOP_LEVEL, getLevelUpThreshold } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const checkMissions = (type: DailyMission['type'], targetId: string | undefined, increment: number) => {
    setGameState(prev => {
      let missionsChanged = false;
      const nextMissions = prev.currentMissions.map(mission => {
        if (mission.isCleared) return mission;

        let shouldIncrement = false;
        if (mission.type === type) {
          if (!mission.targetId || mission.targetId === targetId) {
            shouldIncrement = true;
          }
        }

        if (shouldIncrement) {
          const nextVal = mission.currentValue + increment;
          const isNowCleared = nextVal >= mission.targetValue;
          if (isNowCleared) {
            addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
            missionsChanged = true;
          }
          return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
        }
        return mission;
      });

      if (!missionsChanged && nextMissions === prev.currentMissions) return prev;

      let extraMoney = 0;
      nextMissions.forEach((m, i) => {
        if (m.isCleared && !prev.currentMissions[i].isCleared) {
          extraMoney += 50000;
        }
      });

      // All cleared check
      let bonusMoney = 0;
      let allClaimed = prev.allMissionsBonusClaimed;
      if (!allClaimed && nextMissions.every(m => m.isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        bonusMoney = 150000; // Total reward will be 50k*3 + 150k = 300k
        allClaimed = true;
      }

      return {
        ...prev,
        currentMissions: nextMissions,
        money: prev.money + extraMoney + bonusMoney,
        allMissionsBonusClaimed: allClaimed
      };
    });
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - totalCost,
        ingredients: {
          ...prev.ingredients,
          [type]: prev.ingredients[type] + amount
        }
      }));
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      checkMissions('buy_ingredient', type, amount);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: {
          ...prev.upgrades,
          [key]: prev.upgrades[key] + 1
        }
      }));
      addLog(`設備投資: アップグレードを購入しました (-¥${cost})`);
    }
  };

  const startBaking = (breadType: BreadType) => {
    if (gameState.bakingStatus[breadType] !== null) return;
    const recipe = RECIPES[breadType];
    const currentIngredients = gameState.ingredients;

    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        if ((currentIngredients[key] || 0) < (amount || 0)) {
            addLog(`材料不足: ${recipe.name} を焼くための ${INGREDIENTS_DATA[key].name} が足りません`);
            return;
        }
    }

    const newIngredients = { ...currentIngredients };
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        newIngredients[key] -= (amount || 0);
    }

    setGameState(prev => ({
      ...prev,
      ingredients: newIngredients,
      bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
    }));
    addLog(`調理開始: ${recipe.name} を焼き始めました`);
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let changed = false;
        let bakedCount = 0;
        let bakedType: BreadType | null = null;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const effectiveBakeTime = Math.max(0.1, recipe.bakeTimeSec * speedMultiplier);
            const increment = 100 / (effectiveBakeTime * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成しました！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (bakedCount > 0) {
          setTimeout(() => checkMissions('bake_bread', bakedType!, bakedCount), 0);
        }

        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      let moneyEarnedSession = 0;
      let soldBreads: {type: BreadType, count: number}[] = [];

      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let saleOccurred = false;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];
            if (availableBreads.length === 0) continue; 

            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = 0.3 + (prev.reputation / 200); 
            sellChance *= (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                const isEatIn = Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02);
                if (isEatIn) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                saleOccurred = true;

                const existing = soldBreads.find(sb => sb.type === breadToSell);
                if (existing) existing.count++;
                else soldBreads.push({type: breadToSell, count: 1});
            }
        }

        if (!saleOccurred) return prev;
        moneyEarnedSession = moneyEarned;
        if (lastSoldBread) {
            setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        }
        return {
            ...prev,
            money: prev.money + moneyEarned,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory
        };
      });

      if (moneyEarnedSession > 0) {
        checkMissions('earn_money', undefined, moneyEarnedSession);
        soldBreads.forEach(sb => checkMissions('sell_bread', sb.type, sb.count));
      }
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => {
    setGameState(prev => ({ ...prev, isShopOpen: true }));
    setDailyEvent(null);
    addLog("開店: お店をオープンしました！");
  };
  const closeShopEarly = () => {
    setGameState(prev => ({ ...prev, isShopOpen: false }));
    addLog("閉店: 本日の営業を終了しました。");
  };

  useEffect(() => {
    if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1);
  }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);

  const getAvailableRecipes = () => {
    return Object.values(RECIPES).filter(recipe => recipe.levelRequired <= gameState.shopLevel);
  };

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800">朝の準備中...</h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white"><Icons.Store className="w-6 h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight">AIベーカリー</h1></div>
            </div>
            <div className="flex items-center gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-sm font-bold">{gameState.day}日目</div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1 rounded-full text-sm font-bold shadow"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {getAvailableRecipes().map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50">
                            <h3 className="font-bold text-stone-800 mb-2">{recipe.name}</h3>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden"><div className="bg-amber-500 h-full transition-all duration-100" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm">焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">
                                    {cam.name}
                                </span>
                                {gameState.isShopOpen && (
                                    <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded">
                                        <div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div>
                                        <span className="text-white text-[7px] font-bold font-mono">録画中</span>
                                    </div>
                                )}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene 
                                    lastSale={lastSale} 
                                    inventory={gameState.inventory} 
                                    eatInLevel={gameState.upgrades.eatIn}
                                    cameraPosition={cam.pos}
                                    cameraFov={cam.fov}
                                />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">
                                    信号なし / {cam.name}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase">
                    <span>AI-CCTV v3.5</span>
                    <span className="animate-pulse">{gameState.isShopOpen ? "オンライン" : "スタンバイ"}</span>
                </div>
            </section>

            {/* Daily Missions Board */}
            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm">
                    デイリーミッション
                </div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
                    <Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 今日の目標
                </h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>
                                    {m.description}
                                </span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} 
                                    style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500 uppercase">
                                <span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span>
                                <span>{m.isCleared ? "達成済み" : "進行中"}</span>
                            </div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && (
                        <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg">
                           🎉 全ミッション達成ボーナス獲得！
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {getAvailableRecipes().map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>

                <div className="mt-4 pt-4 border-t border-amber-100">
                    <h3 className="text-sm font-bold text-amber-800 mb-2">店舗レベル: {gameState.shopLevel}</h3>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    <div className="flex justify-between items-center">
                        <span className="text-[10px] text-gray-500">実績: {gameState.levelProgressSales}個</span>
                        {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                            <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="py-1 px-3 bg-orange-500 text-white text-[10px] font-bold rounded-lg animate-bounce">レベルUP可能</button>
                        )}
                    </div>
                </div>

                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2">次の日へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>

            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1">> {log}</div>)}
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー (仕入れ)</h2>
                <div className="mb-3 bg-amber-50 p-2 rounded text-[10px] text-amber-800 flex justify-between items-center border border-amber-100">
                   <span>本日の価格相場:</span>
                   <span className="font-bold">{(dailyEvent?.costModifier || 1.0).toFixed(2)}倍</span>
                </div>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const costModifier = dailyEvent?.costModifier || 1.0;
                        const unitCost = Math.floor(item.cost * costModifier);
                        const isExpensive = costModifier > 1.0;
                        const isCheap = costModifier < 1.0;
                        const purchaseOptions = [1, 10, 50];

                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl hover:bg-stone-50 transition-colors">
                                <div className="flex items-center justify-between mb-3">
                                    <div>
                                        <div className="font-bold text-stone-700 text-sm">{item.name}</div>
                                        <div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div>
                                    </div>
                                    <div className={`text-[10px] font-bold px-2 py-0.5 rounded ${isExpensive ? 'text-red-500' : isCheap ? 'text-green-600' : 'text-stone-400'}`}>
                                        単価 ¥{unitCost}
                                    </div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {purchaseOptions.map(amount => {
                                        const totalCost = unitCost * amount;
                                        const canAfford = gameState.money >= totalCost;
                                        return (
                                            <button 
                                                key={amount}
                                                onClick={() => buyIngredient(item.id, amount)}
                                                disabled={!canAfford}
                                                className={`py-2 px-1 rounded-lg text-[10px] font-bold flex flex-col items-center transition-all border
                                                    ${canAfford 
                                                        ? 'bg-white text-stone-700 hover:bg-amber-50 border-stone-200 active:scale-95' 
                                                        : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}
                                                `}
                                            >
                                                <span className="opacity-70">x{amount}</span>
                                                <span>¥{totalCost.toLocaleString()}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum IngredientType {
  FLOUR = 'flour',
  SUGAR = 'sugar',
  BUTTER = 'butter',
  YEAST = 'yeast',
  MILK = 'milk',
  EGGS = 'eggs',
  SALT = 'salt',
  CHOCO = 'choco',
  ANKO = 'anko',
  CURRY = 'curry'
}

export enum BreadType {
  SHOKUPAN = 'shokupan',
  ANPAN = 'anpan',
  CREAMPAN = 'creampan',
  SHIOPAN = 'shiopan',
  MELONPAN = 'melonpan',
  CURRYPAN = 'currypan',
  CORNET = 'cornet',
  BAGUETTE = 'baguette',
  BAGEL = 'bagel',
  EPI = 'epi',
  CROISSANT = 'croissant',
  CINNAMON = 'cinnamon',
  FOCACCIA = 'focaccia',
  PRETZEL = 'pretzel',
  DANISH = 'danish',
  BRIOCHE = 'brioche',
  RYE = 'rye',
  SOURDOUGH = 'sourdough',
  PANETTONE = 'panettone'
}

export interface DailyMission {
  id: string;
  description: string;
  targetValue: number;
  currentValue: number;
  type: 'sell_bread' | 'bake_bread' | 'earn_money' | 'buy_ingredient';
  targetId?: string; // BreadType or IngredientType
  isCleared: boolean;
}

export interface Ingredient {
  id: IngredientType;
  name: string;
  cost: number;
  stock: number;
  unit: string;
}

export interface BreadRecipe {
  id: BreadType;
  name: string;
  description: string;
  basePrice: number;
  ingredients: { [key in IngredientType]?: number };
  batchSize: number;
  levelRequired: number;
  bakeTimeSec: number;
}

export interface DailyEvent {
  day: number;
  weather: string;
  trend: BreadType | null;
  trendReason: string;
  customerSentiment: string;
  salesModifier: number;
  costModifier: number;
  missions: DailyMission[];
}

export interface UpgradeStats {
  speed: number;
  batch: number;
  promo: number;
  branches: number;
  eatIn: number;
}

export interface GameState {
  money: number;
  day: number;
  dailyEarnings: number; // New: Track sales for the current day
  reputation: number;
  shopLevel: number;
  levelProgressSales: number;
  ingredients: Record<IngredientType, number>;
  inventory: Record<BreadType, number>;
  isShopOpen: boolean;
  bakingStatus: Record<BreadType, number | null>;
  upgrades: UpgradeStats;
  currentMissions: DailyMission[];
  allMissionsBonusClaimed: boolean;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, MAX_SHOP_LEVEL, getLevelUpThreshold } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const checkMissions = (type: DailyMission['type'], targetId: string | undefined, increment: number) => {
    setGameState(prev => {
      let missionsChanged = false;
      const nextMissions = prev.currentMissions.map(mission => {
        if (mission.isCleared) return mission;

        let shouldIncrement = false;
        if (mission.type === type) {
          if (!mission.targetId || mission.targetId === targetId) {
            shouldIncrement = true;
          }
        }

        if (shouldIncrement) {
          const nextVal = mission.currentValue + increment;
          const isNowCleared = nextVal >= mission.targetValue;
          if (isNowCleared) {
            addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
            missionsChanged = true;
          }
          return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
        }
        return mission;
      });

      if (!missionsChanged && nextMissions === prev.currentMissions) return prev;

      let extraMoney = 0;
      nextMissions.forEach((m, i) => {
        if (m.isCleared && !prev.currentMissions[i].isCleared) {
          extraMoney += 50000;
        }
      });

      // All cleared check
      let bonusMoney = 0;
      let allClaimed = prev.allMissionsBonusClaimed;
      if (!allClaimed && nextMissions.every(m => m.isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        bonusMoney = 150000; // Total reward will be 50k*3 + 150k = 300k
        allClaimed = true;
      }

      return {
        ...prev,
        currentMissions: nextMissions,
        money: prev.money + extraMoney + bonusMoney,
        allMissionsBonusClaimed: allClaimed
      };
    });
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - totalCost,
        ingredients: {
          ...prev.ingredients,
          [type]: prev.ingredients[type] + amount
        }
      }));
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      checkMissions('buy_ingredient', type, amount);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: {
          ...prev.upgrades,
          [key]: prev.upgrades[key] + 1
        }
      }));
      addLog(`設備投資: アップグレードを購入しました (-¥${cost})`);
    }
  };

  const startBaking = (breadType: BreadType) => {
    if (gameState.bakingStatus[breadType] !== null) return;
    const recipe = RECIPES[breadType];
    const currentIngredients = gameState.ingredients;

    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        if ((currentIngredients[key] || 0) < (amount || 0)) {
            addLog(`材料不足: ${recipe.name} を焼くための ${INGREDIENTS_DATA[key].name} が足りません`);
            return;
        }
    }

    const newIngredients = { ...currentIngredients };
    for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
        const key = ingKey as IngredientType;
        newIngredients[key] -= (amount || 0);
    }

    setGameState(prev => ({
      ...prev,
      ingredients: newIngredients,
      bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
    }));
    addLog(`調理開始: ${recipe.name} を焼き始めました`);
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let changed = false;
        let bakedCount = 0;
        let bakedType: BreadType | null = null;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const effectiveBakeTime = Math.max(0.1, recipe.bakeTimeSec * speedMultiplier);
            const increment = 100 / (effectiveBakeTime * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成しました！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (bakedCount > 0) {
          setTimeout(() => checkMissions('bake_bread', bakedType!, bakedCount), 0);
        }

        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      let moneyEarnedSession = 0;
      let soldBreads: {type: BreadType, count: number}[] = [];

      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let saleOccurred = false;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];
            if (availableBreads.length === 0) continue; 

            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = 0.3 + (prev.reputation / 200); 
            sellChance *= (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                const isEatIn = Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02);
                if (isEatIn) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                saleOccurred = true;

                const existing = soldBreads.find(sb => sb.type === breadToSell);
                if (existing) existing.count++;
                else soldBreads.push({type: breadToSell, count: 1});
            }
        }

        if (!saleOccurred) return prev;
        moneyEarnedSession = moneyEarned;
        if (lastSoldBread) {
            setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        }
        return {
            ...prev,
            money: prev.money + moneyEarned,
            dailyEarnings: prev.dailyEarnings + moneyEarned, // Accumulate daily sales
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory
        };
      });

      if (moneyEarnedSession > 0) {
        checkMissions('earn_money', undefined, moneyEarnedSession);
        soldBreads.forEach(sb => checkMissions('sell_bread', sb.type, sb.count));
      }
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    // Reset daily earnings at the start of the preparation
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0 }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => {
    setGameState(prev => ({ ...prev, isShopOpen: true }));
    setDailyEvent(null);
    addLog("開店: お店をオープンしました！");
  };
  const closeShopEarly = () => {
    setGameState(prev => ({ ...prev, isShopOpen: false }));
    addLog("閉店: 本日の営業を終了しました。");
  };

  useEffect(() => {
    if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1);
  }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);

  const getAvailableRecipes = () => {
    return Object.values(RECIPES).filter(recipe => recipe.levelRequired <= gameState.shopLevel);
  };

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800">朝の準備中...</h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white"><Icons.Store className="w-6 h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight">AIベーカリー</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-xs sm:text-sm font-bold">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-[10px] text-amber-600 font-bold uppercase tracking-tighter">本日売上</div>
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-xs sm:text-sm font-bold">
                    <span className="hidden sm:inline">総資金:</span> ¥{gameState.money.toLocaleString()}
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1 rounded-full text-sm font-bold shadow transition-transform active:scale-95"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {getAvailableRecipes().map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50">
                            <h3 className="font-bold text-stone-800 mb-2">{recipe.name}</h3>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden"><div className="bg-amber-500 h-full transition-all duration-100" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm">焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">
                                    {cam.name}
                                </span>
                                {gameState.isShopOpen && (
                                    <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded">
                                        <div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div>
                                        <span className="text-white text-[7px] font-bold font-mono uppercase tracking-wider">録画中</span>
                                    </div>
                                )}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene 
                                    lastSale={lastSale} 
                                    inventory={gameState.inventory} 
                                    eatInLevel={gameState.upgrades.eatIn}
                                    cameraPosition={cam.pos}
                                    cameraFov={cam.fov}
                                />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">
                                    信号なし / {cam.name}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase">
                    <span>AI-CCTV v3.5</span>
                    <span className="animate-pulse">{gameState.isShopOpen ? "オンライン" : "スタンバイ"}</span>
                </div>
            </section>

            {/* Daily Missions Board */}
            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm uppercase">
                    今日の目標
                </div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2">
                    <Icons.TrendingUp className="w-5 h-5 text-amber-600" /> デイリーミッション
                </h2>

                <div className="mb-4 bg-amber-50 p-3 rounded-xl border border-amber-100 flex justify-between items-center">
                    <div className="text-xs font-bold text-amber-700">本日売上</div>
                    <div className="text-lg font-bold text-amber-900 font-mono">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>

                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>
                                    {m.description}
                                </span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} 
                                    style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500 uppercase">
                                <span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span>
                                <span>{m.isCleared ? "達成済み" : "進行中"}</span>
                            </div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && (
                        <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg">
                           🎉 全ミッション達成！ボーナス ¥150,000 獲得
                        </div>
                    )}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {getAvailableRecipes().map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>

                <div className="mt-4 pt-4 border-t border-amber-100">
                    <h3 className="text-sm font-bold text-amber-800 mb-2">店舗レベル: {gameState.shopLevel}</h3>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    <div className="flex justify-between items-center">
                        <span className="text-[10px] text-gray-500">実績: {gameState.levelProgressSales}個</span>
                        {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                            <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="py-1 px-3 bg-orange-500 text-white text-[10px] font-bold rounded-lg animate-bounce">レベルUP可能</button>
                        )}
                    </div>
                </div>

                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2">次の日へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>

            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1">> {log}</div>)}
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー (仕入れ)</h2>
                <div className="mb-3 bg-amber-50 p-2 rounded text-[10px] text-amber-800 flex justify-between items-center border border-amber-100">
                   <span>本日の価格相場:</span>
                   <span className="font-bold">{(dailyEvent?.costModifier || 1.0).toFixed(2)}倍</span>
                </div>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const costModifier = dailyEvent?.costModifier || 1.0;
                        const unitCost = Math.floor(item.cost * costModifier);
                        const isExpensive = costModifier > 1.0;
                        const isCheap = costModifier < 1.0;
                        const purchaseOptions = [1, 10, 50];

                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl hover:bg-stone-50 transition-colors">
                                <div className="flex items-center justify-between mb-3">
                                    <div>
                                        <div className="font-bold text-stone-700 text-sm">{item.name}</div>
                                        <div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div>
                                    </div>
                                    <div className={`text-[10px] font-bold px-2 py-0.5 rounded ${isExpensive ? 'text-red-500' : isCheap ? 'text-green-600' : 'text-stone-400'}`}>
                                        単価 ¥{unitCost}
                                    </div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {purchaseOptions.map(amount => {
                                        const totalCost = unitCost * amount;
                                        const canAfford = gameState.money >= totalCost;
                                        return (
                                            <button 
                                                key={amount}
                                                onClick={() => buyIngredient(item.id, amount)}
                                                disabled={!canAfford}
                                                className={`py-2 px-1 rounded-lg text-[10px] font-bold flex flex-col items-center transition-all border
                                                    ${canAfford 
                                                        ? 'bg-white text-stone-700 hover:bg-amber-50 border-stone-200 active:scale-95' 
                                                        : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}
                                                `}
                                            >
                                                <span className="opacity-70">x{amount}</span>
                                                <span>¥{totalCost.toLocaleString()}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

