import React from 'react';
import { UpgradeStats } from '../types';
import { UPGRADES_DATA } from '../constants';
import { Icons } from './Icon';

interface UpgradeModalProps {
  currentMoney: number;
  upgrades: UpgradeStats;
  onBuy: (key: keyof UpgradeStats, cost: number) => void;
  onClose: () => void;
}

export const UpgradeModal: React.FC<UpgradeModalProps> = ({ currentMoney, upgrades, onBuy, onClose }) => {

  const getCost = (key: keyof UpgradeStats, currentLevel: number) => {
    const data = UPGRADES_DATA[key];
    return Math.floor(data.baseCost * Math.pow(data.costMultiplier, currentLevel));
  };

  const renderUpgradeItem = (key: keyof UpgradeStats, icon: React.ReactNode) => {
    const data = UPGRADES_DATA[key];
    const currentLevel = upgrades[key];
    const isMaxed = currentLevel >= data.maxLevel;

    const cost = getCost(key, currentLevel);
    const canAfford = currentMoney >= cost;

    return (
      <div key={key} className="bg-white border border-stone-200 rounded-xl p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex items-start gap-3">
          <div className={`p-3 rounded-lg ${isMaxed ? 'bg-amber-100 text-amber-500' : 'bg-blue-100 text-blue-600'}`}>
            {icon}
          </div>
          <div className="flex-1">
            <h3 className="font-bold text-stone-800 flex items-center gap-2">
              {data.name} 
              <span className="text-xs bg-stone-100 px-2 py-0.5 rounded text-stone-500">
                {key === 'branches' ? `${currentLevel}店舗` : key === 'staff' ? `${currentLevel}人` : `Lv.${currentLevel}`} / {data.maxLevel}
              </span>
            </h3>
            <p className="text-xs text-stone-500 mt-1">{data.description}</p>
          </div>
        </div>

        {isMaxed ? (
          <div className="px-6 py-2 bg-gray-100 text-gray-400 font-bold rounded-lg text-sm whitespace-nowrap">
            MAX
          </div>
        ) : (
          <button
            onClick={() => onBuy(key, cost)}
            disabled={!canAfford}
            className={`px-4 py-2 rounded-lg font-bold text-sm flex flex-col items-center min-w-[100px] transition-all
              ${canAfford 
                ? 'bg-amber-500 hover:bg-amber-600 text-white shadow-md active:translate-y-0.5' 
                : 'bg-gray-100 text-gray-400 cursor-not-allowed'}
            `}
          >
            <span>{key === 'branches' ? '開店する' : key === 'staff' ? '採用する' : '強化する'}</span>
            <span className="text-xs opacity-90">¥{cost.toLocaleString()}</span>
          </button>
        )}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
      <div className="bg-stone-50 rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden border-4 border-amber-500 flex flex-col max-h-[90vh]">
        <div className="bg-amber-500 p-4 flex justify-between items-center text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Icons.Hammer className="w-6 h-6" />
            設備投資・アップグレード
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-white/20 rounded-full transition-colors">
            <Icons.AlertCircle className="w-6 h-6 rotate-45" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-4 custom-scrollbar">
          <div className="bg-yellow-100 p-3 rounded-lg flex items-center gap-2 text-yellow-800 text-sm font-bold mb-4">
            <Icons.Coins className="w-5 h-5" />
            現在の資金: ¥{currentMoney.toLocaleString()}
          </div>

          {renderUpgradeItem('staff', <Icons.Users className="w-6 h-6" />)}
          <hr className="border-stone-200 my-2" />
          {renderUpgradeItem('branches', <Icons.Building2 className="w-6 h-6" />)}
          {renderUpgradeItem('speed', <Icons.Zap className="w-6 h-6" />)}
          {renderUpgradeItem('batch', <Icons.PackagePlus className="w-6 h-6" />)}
          {renderUpgradeItem('promo', <Icons.Megaphone className="w-6 h-6" />)}
          {renderUpgradeItem('eatIn', <Icons.Coffee className="w-6 h-6" />)}
        </div>

        <div className="p-4 border-t border-stone-200 bg-white">
             <button onClick={onClose} className="w-full py-3 bg-stone-200 hover:bg-stone-300 text-stone-700 font-bold rounded-xl transition-colors">
                閉じる
             </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0,
      staff: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  const checkMissions = (type: DailyMission['type'], targetId: string | undefined, increment: number) => {
    setGameState(prev => {
      let missionsChanged = false;
      const nextMissions = prev.currentMissions.map(mission => {
        if (mission.isCleared) return mission;
        let shouldIncrement = (mission.type === type && (!mission.targetId || mission.targetId === targetId));

        if (shouldIncrement) {
          const nextVal = mission.currentValue + increment;
          const isNowCleared = nextVal >= mission.targetValue;
          if (isNowCleared) {
            addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
            missionsChanged = true;
          }
          return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
        }
        return mission;
      });

      if (!missionsChanged && nextMissions === prev.currentMissions) return prev;

      let extraMoney = 0;
      nextMissions.forEach((m, i) => {
        if (m.isCleared && !prev.currentMissions[i].isCleared) extraMoney += 50000;
      });

      let bonusMoney = 0;
      let allClaimed = prev.allMissionsBonusClaimed;
      if (!allClaimed && nextMissions.every(m => m.isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        bonusMoney = 150000;
        allClaimed = true;
      }

      return {
        ...prev,
        currentMissions: nextMissions,
        money: prev.money + extraMoney + bonusMoney,
        allMissionsBonusClaimed: allClaimed
      };
    });
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - totalCost,
        ingredients: { ...prev.ingredients, [type]: prev.ingredients[type] + amount }
      }));
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      checkMissions('buy_ingredient', type, amount);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 }
      }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) {
        canBake = false;
        return prev;
      }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false;
              return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          newIngredients[ingKey as IngredientType] -= (amount || 0);
      }
      return {
        ...prev,
        ingredients: newIngredients,
        bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
      };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff = gameState.upgrades.staff - currentBakingCount;
      if (availableStaff <= 0) return;

      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && 
               gameState.inventory[type] < 5 && 
               gameState.bakingStatus[type] === null;
      });

      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (bakedType) setTimeout(() => checkMissions('bake_bread', bakedType!, bakedCount), 0);
        return changed ? { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory } : prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      let moneyEarnedSession = 0;
      let soldBreads: {type: BreadType, count: number}[] = [];

      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = Object.keys(currentInventory).filter(k => currentInventory[k as BreadType] > 0) as BreadType[];
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;
                const existing = soldBreads.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldBreads.push({type: breadToSell, count: 1});
            }
        }

        if (moneyEarned === 0) return prev;
        moneyEarnedSession = moneyEarned;
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return {
            ...prev,
            money: prev.money + moneyEarned,
            dailyEarnings: prev.dailyEarnings + moneyEarned,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory
        };
      });

      if (moneyEarnedSession > 0) {
        checkMissions('earn_money', undefined, moneyEarnedSession);
        soldBreads.forEach(sb => checkMissions('sell_bread', sb.type, sb.count));
      }
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);

    setGameState(prev => ({ 
      ...prev, 
      isShopOpen: false, 
      allMissionsBonusClaimed: false, 
      dailyEarnings: 0,
      money: prev.money - wages
    }));

    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };

  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-[8px] sm:text-[10px] text-amber-600 font-bold uppercase tracking-tighter">本日売上</div>
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-xs sm:text-sm font-bold shadow-sm">
                    <span className="hidden sm:inline">資金:</span> ¥{gameState.money.toLocaleString()}
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800">{recipe.name}</h3>
                                <span className="text-[10px] text-stone-400 font-mono">ID: {recipe.id}</span>
                            </div>
                            <div className="flex flex-wrap gap-1.5 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded-md ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden shadow-inner"><div className="bg-amber-500 h-full transition-all duration-100 relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm transition-transform active:scale-95">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">SIGNAL LOSS</div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase tracking-widest px-2"><span>AI-BAKERY SYSTEM v4.2</span><span className="animate-pulse">{gameState.isShopOpen ? "RUNNING" : "STANDBY"}</span></div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl">目標</div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> デイリーミッション</h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden shadow-inner"><div className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div></div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500"><span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span><span>{m.isCleared ? "達成済み" : "進行中"}</span></div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg">🎉 ボーナス ¥150,000 獲得</div>}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-xs font-bold text-amber-800">店舗ランク: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">累計販売: {gameState.levelProgressSales}個</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2 shadow-inner"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="w-full py-1.5 bg-orange-500 text-white text-xs font-bold rounded-lg animate-pulse shadow-md">ランクUP！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-3">
                                    <div><div className="font-bold text-stone-700 text-sm">{item.name}</div><div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div></div>
                                    <div className="text-[10px] font-bold bg-white border border-stone-200 px-2 py-1 rounded-md shadow-sm">¥{unitCost}/個</div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button key={amount} onClick={() => buyIngredient(item.id, amount)} disabled={gameState.money < (unitCost * amount)} className={`py-2 rounded-lg text-[10px] font-bold flex flex-col items-center border transition-all ${gameState.money >= (unitCost * amount) ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' : 'bg-gray-50 text-gray-300 border-gray-100'}`}>
                                            <span className="opacity-60">x{amount}</span><span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar border border-stone-700">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1 opacity-80">> {log}</div>)}
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0,
      staff: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  // Improved mission checking logic that can be used inside functional state updates
  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    let missionsChanged = false;

    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;

      let nextVal = mission.currentValue;

      // 'earn_money' mission is special: always sync with total daily earnings
      if (mission.type === 'earn_money') {
        nextVal = currentDailyEarnings;
      } else if (mission.type === type && (!mission.targetId || mission.targetId === targetId)) {
        nextVal += increment;
      } else {
        return mission;
      }

      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
        missionsChanged = true;
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });

    let allBonus = false;
    if (nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
        allBonus = true;
    }

    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => {
        const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, amount, prev.dailyEarnings);
        return {
          ...prev,
          money: prev.money - totalCost + reward,
          ingredients: { ...prev.ingredients, [type]: prev.ingredients[type] + amount },
          currentMissions: missions,
          allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
        };
      });
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 }
      }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) {
        canBake = false;
        return prev;
      }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false;
              return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          newIngredients[ingKey as IngredientType] -= (amount || 0);
      }
      return {
        ...prev,
        ingredients: newIngredients,
        bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
      };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff = gameState.upgrades.staff - currentBakingCount;
      if (availableStaff <= 0) return;

      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && 
               gameState.inventory[type] < 5 && 
               gameState.bakingStatus[type] === null;
      });

      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;

            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions;
                totalReward += reward;
                if (allBonus) finalAllBonus = true;
            }

            return { 
                ...prev, 
                bakingStatus: nextBakingStatus, 
                inventory: nextInventory,
                currentMissions: nextMissions,
                money: prev.money + totalReward,
                allMissionsBonusClaimed: finalAllBonus
            };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;

                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }

        if (moneyEarned === 0) return prev;

        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;

        // Update missions for both 'earn_money' (absolute) and 'sell_bread' (incremental)
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);

        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions;
            totalReward += result.reward;
            if (result.allBonus) allBonus = true;
        });

        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });

        return {
            ...prev,
            money: prev.money + moneyEarned + totalReward,
            dailyEarnings: nextDailyEarnings,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory,
            currentMissions: nextMissions,
            allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
        };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);

    // Reset daily earnings and reset all mission current values at the start of day
    setGameState(prev => ({ 
      ...prev, 
      isShopOpen: false, 
      allMissionsBonusClaimed: false, 
      dailyEarnings: 0,
      money: prev.money - wages
    }));

    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };

  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-[8px] sm:text-[10px] text-amber-600 font-bold uppercase tracking-tighter">本日売上</div>
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-xs sm:text-sm font-bold shadow-sm">
                    <span className="hidden sm:inline">資金:</span> ¥{gameState.money.toLocaleString()}
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800">{recipe.name}</h3>
                                <span className="text-[10px] text-stone-400 font-mono">ID: {recipe.id}</span>
                            </div>
                            <div className="flex flex-wrap gap-1.5 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[10px] px-2 py-0.5 rounded-md ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden shadow-inner"><div className="bg-amber-500 h-full transition-all duration-100 relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg shadow-sm transition-transform active:scale-95">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            {gameState.isShopOpen ? (
                                <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-stone-600 font-mono text-[8px] uppercase">SIGNAL LOSS</div>
                            )}
                        </div>
                    ))}
                </div>
                <div className="p-1 flex justify-between items-center text-[8px] text-stone-500 font-mono uppercase tracking-widest px-2"><span>AI-BAKERY SYSTEM v4.2</span><span className="animate-pulse">{gameState.isShopOpen ? "RUNNING" : "STANDBY"}</span></div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 overflow-hidden relative">
                <div className="absolute top-0 right-0 bg-amber-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl">目標</div>
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> デイリーミッション</h2>

                {/* Visual confirmation of daily earnings on the mission board */}
                <div className="mb-4 bg-amber-50 p-3 rounded-xl border border-amber-100 flex justify-between items-center">
                    <div className="text-xs font-bold text-amber-700">本日売上合計:</div>
                    <div className="text-lg font-bold text-amber-900">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>

                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200 shadow-inner' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-xs font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-4 h-4 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1.5 overflow-hidden shadow-inner">
                                <div 
                                    className={`h-full transition-all duration-500 ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} 
                                    style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="flex justify-between mt-1 text-[8px] font-mono text-stone-500">
                                <span>{m.currentValue.toLocaleString()} / {m.targetValue.toLocaleString()}</span>
                                <span>{m.isCleared ? "達成済み" : "進行中"}</span>
                            </div>
                        </div>
                    ))}
                    {gameState.allMissionsBonusClaimed && <div className="bg-indigo-600 text-white text-center py-2 rounded-lg text-xs font-bold animate-bounce shadow-lg mt-4">🎉 全ミッション達成ボーナス獲得！</div>}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />店頭在庫</h2>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                            <InventoryItem key={recipe.id} variant="bread" name={recipe.name} count={gameState.inventory[recipe.id]} unit="個" icon={<Icons.Wheat className="w-4 h-4 text-amber-600"/>}/>
                        ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-xs font-bold text-amber-800">店舗ランク: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">累計販売: {gameState.levelProgressSales}個</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-2 mb-2 shadow-inner"><div className="bg-orange-500 h-2 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="w-full py-1.5 bg-orange-500 text-white text-xs font-bold rounded-lg animate-pulse shadow-md">ランクUP！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-3 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        return (
                            <div key={item.id} className="p-4 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-3">
                                    <div><div className="font-bold text-stone-700 text-sm">{item.name}</div><div className="text-xs text-stone-500">在庫: {gameState.ingredients[item.id]}{item.unit}</div></div>
                                    <div className="text-[10px] font-bold bg-white border border-stone-200 px-2 py-1 rounded-md shadow-sm">¥{unitCost}/個</div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button key={amount} onClick={() => buyIngredient(item.id, amount)} disabled={gameState.money < (unitCost * amount)} className={`py-2 rounded-lg text-[10px] font-bold flex flex-col items-center border transition-all ${gameState.money >= (unitCost * amount) ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' : 'bg-gray-50 text-gray-300 border-gray-100'}`}>
                                            <span className="opacity-60">x{amount}</span><span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
            <section className="bg-stone-800 rounded-2xl shadow-inner p-4 h-24 overflow-y-auto font-mono text-[10px] text-stone-400 custom-scrollbar border border-stone-700">
                {logs.map((log, i) => <div key={i} className="mb-1 border-b border-stone-700/30 pb-1 opacity-80">> {log}</div>)}
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum IngredientType {
  FLOUR = 'flour',
  SUGAR = 'sugar',
  BUTTER = 'butter',
  YEAST = 'yeast',
  MILK = 'milk',
  EGGS = 'eggs',
  SALT = 'salt',
  CHOCO = 'choco',
  ANKO = 'anko',
  CURRY = 'curry',
  VEGETABLES = 'vegetables',
  MEAT = 'meat',
  FISH = 'fish'
}

export enum BreadType {
  SHOKUPAN = 'shokupan',
  ANPAN = 'anpan',
  CREAMPAN = 'creampan',
  SHIOPAN = 'shiopan',
  MELONPAN = 'melonpan',
  CURRYPAN = 'currypan',
  CORNET = 'cornet',
  BAGUETTE = 'baguette',
  BAGEL = 'bagel',
  EPI = 'epi',
  CROISSANT = 'croissant',
  CINNAMON = 'cinnamon',
  FOCACCIA = 'focaccia',
  PRETZEL = 'pretzel',
  DANISH = 'danish',
  BRIOCHE = 'brioche',
  RYE = 'rye',
  SOURDOUGH = 'sourdough',
  PANETTONE = 'panettone',
  SANDWICH = 'sandwich',
  TUNAPAN = 'tunapan',
  MEATPIE = 'meatpie'
}

export interface DailyMission {
  id: string;
  description: string;
  targetValue: number;
  currentValue: number;
  type: 'sell_bread' | 'bake_bread' | 'earn_money' | 'buy_ingredient';
  targetId?: string; // BreadType or IngredientType
  isCleared: boolean;
}

export interface Ingredient {
  id: IngredientType;
  name: string;
  cost: number;
  stock: number;
  unit: string;
}

export interface BreadRecipe {
  id: BreadType;
  name: string;
  description: string;
  basePrice: number;
  ingredients: { [key in IngredientType]?: number };
  batchSize: number;
  levelRequired: number;
  bakeTimeSec: number;
}

export interface DailyEvent {
  day: number;
  weather: string;
  trend: BreadType | null;
  trendReason: string;
  customerSentiment: string;
  salesModifier: number;
  costModifier: number;
  missions: DailyMission[];
}

export interface UpgradeStats {
  speed: number;
  batch: number;
  promo: number;
  branches: number;
  eatIn: number;
  staff: number; // New: Number of hired staff
}

export interface GameState {
  money: number;
  day: number;
  dailyEarnings: number;
  reputation: number;
  shopLevel: number;
  levelProgressSales: number;
  ingredients: Record<IngredientType, number>;
  inventory: Record<BreadType, number>;
  isShopOpen: boolean;
  bakingStatus: Record<BreadType, number | null>;
  upgrades: UpgradeStats;
  currentMissions: DailyMission[];
  allMissionsBonusClaimed: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100,
      [IngredientType.SUGAR]: 100,
      [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100,
      [IngredientType.MILK]: 50,
      [IngredientType.EGGS]: 50,
      [IngredientType.SALT]: 50,
      [IngredientType.CHOCO]: 20,
      [IngredientType.ANKO]: 20,
      [IngredientType.CURRY]: 20,
      [IngredientType.VEGETABLES]: 20,
      [IngredientType.MEAT]: 10,
      [IngredientType.FISH]: 10,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: {
      speed: 0,
      batch: 0,
      promo: 0,
      branches: 1,
      eatIn: 0,
      staff: 0
    },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 50));
  };

  // Improved mission checking logic that can be used inside functional state updates
  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    let missionsChanged = false;

    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;

      let nextVal = mission.currentValue;

      // 'earn_money' mission is special: always sync with total daily earnings
      if (mission.type === 'earn_money') {
        nextVal = currentDailyEarnings;
      } else if (mission.type === type && (!mission.targetId || mission.targetId === targetId)) {
        nextVal += increment;
      } else {
        return mission;
      }

      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
        missionsChanged = true;
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });

    let allBonus = false;
    if (nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared)) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
        allBonus = true;
    }

    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);
    const totalCost = unitCost * amount;

    if (gameState.money >= totalCost) {
      setGameState(prev => {
        const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, amount, prev.dailyEarnings);
        return {
          ...prev,
          money: prev.money - totalCost + reward,
          ingredients: { ...prev.ingredients, [type]: prev.ingredients[type] + amount },
          currentMissions: missions,
          allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
        };
      });
      addLog(`仕入れ: ${item.name} を${amount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
    } else {
      addLog(`資金不足: ${item.name} ${amount}個 分の資金が足りません`);
    }
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({
        ...prev,
        money: prev.money - cost,
        upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 }
      }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) {
        canBake = false;
        return prev;
      }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false;
              return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          newIngredients[ingKey as IngredientType] -= (amount || 0);
      }
      return {
        ...prev,
        ingredients: newIngredients,
        bakingStatus: { ...prev.bakingStatus, [breadType]: 0 }
      };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff = gameState.upgrades.staff - currentBakingCount;
      if (availableStaff <= 0) return;

      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && 
               gameState.inventory[type] < 5 && 
               gameState.bakingStatus[type] === null;
      });

      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;

        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;

            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount;
              bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else {
              nextBakingStatus[breadType] = newProgress;
            }
            changed = true;
          }
        });

        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;

            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions;
                totalReward += reward;
                if (allBonus) finalAllBonus = true;
            }

            return { 
                ...prev, 
                bakingStatus: nextBakingStatus, 
                inventory: nextInventory,
                currentMissions: nextMissions,
                money: prev.money + totalReward,
                allMissionsBonusClaimed: finalAllBonus
            };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) {
                sellChance *= dailyEvent.salesModifier;
                if (dailyEvent.trend === breadToSell) sellChance *= 1.5; 
            }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price;
                salesCountTotal += 1;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;

                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }

        if (moneyEarned === 0) return prev;

        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;

        // Update missions for both 'earn_money' (absolute) and 'sell_bread' (incremental)
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);

        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions;
            totalReward += result.reward;
            if (result.allBonus) allBonus = true;
        });

        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });

        return {
            ...prev,
            money: prev.money + moneyEarned + totalReward,
            dailyEarnings: nextDailyEarnings,
            reputation: prev.reputation + 0.1,
            levelProgressSales: prev.levelProgressSales + salesCountTotal,
            inventory: currentInventory,
            currentMissions: nextMissions,
            allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
        };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);

    // Reset daily earnings and reset all mission current values at the start of day
    setGameState(prev => ({ 
      ...prev, 
      isShopOpen: false, 
      allMissionsBonusClaimed: false, 
      dailyEarnings: 0,
      money: prev.money - wages
    }));

    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };

  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}

      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-[8px] sm:text-[10px] text-amber-600 font-bold uppercase tracking-tighter">本日売上</div>
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.dailyEarnings.toLocaleString()}</div>
                </div>
                <div className="bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 text-xs sm:text-sm font-bold shadow-sm">
                    <span className="hidden sm:inline">資金:</span> ¥{gameState.money.toLocaleString()}
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
