import React, { useRef, useState, useEffect, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Text, ContactShadows } from '@react-three/drei';
import * as THREE from 'three';
import { BreadType, ShopCustomization, TimePhase } from '../types';
import { RECIPES } from '../constants';

interface CustomerProps {
  id: number;
  breadType: BreadType;
  onLeave: (id: number) => void;
}

const Customer: React.FC<CustomerProps> = ({ id, breadType, onLeave }) => {
  const groupRef = useRef<THREE.Group>(null);
  const [state, setState] = useState<'entering' | 'buying' | 'leaving'>('entering');
  const [timer, setTimer] = useState(0);
  const color = useRef(new THREE.Color().setHSL(Math.random(), 0.7, 0.6));

  useFrame((rootState, delta) => {
    if (!groupRef.current) return;
    const time = rootState.clock.getElapsedTime();
    const bounce = Math.sin(time * 15) * 0.1;

    if (state === 'entering') {
      groupRef.current.position.x += delta * 3;
      groupRef.current.position.y = bounce;
      if (groupRef.current.position.x >= -1.5) { setState('buying'); setTimer(0); }
    } else if (state === 'buying') {
      setTimer(prev => prev + delta);
      groupRef.current.position.y = 0;
      if (timer > 1.0) setState('leaving');
    } else if (state === 'leaving') {
      groupRef.current.position.x += delta * 3;
      groupRef.current.position.y = bounce;
      if (groupRef.current.position.x > 5) onLeave(id);
    }
  });

  const recipe = RECIPES[breadType];
  return (
    <group ref={groupRef} position={[-6, 0, 0]}>
      <mesh position={[0, 0.6, 0]} castShadow><capsuleGeometry args={[0.3, 0.6, 4, 8]} /><meshStandardMaterial color={color.current} /></mesh>
      <mesh position={[0, 1.2, 0]} castShadow><sphereGeometry args={[0.25, 16, 16]} /><meshStandardMaterial color="#ffdec7" /></mesh>
      {(state === 'buying' || state === 'leaving') && (
        <group position={[0, 2.2, 0]}>
          <Text fontSize={0.3} color="#5c4033" anchorX="center" anchorY="middle" outlineWidth={0.02} outlineColor="white">
            {recipe?.name?.substring(0, 4) || "創作パン"}
          </Text>
        </group>
      )}
    </group>
  );
};

const BreadMesh: React.FC<{ type: BreadType }> = ({ type }) => {
  const color = useMemo(() => {
    switch(type) {
      case BreadType.SHOKUPAN: return '#f5deb3';
      case BreadType.ANPAN: return '#8b4513';
      case BreadType.BAGUETTE: return '#cd853f';
      default: return '#deb887';
    }
  }, [type]);
  return (
    <mesh castShadow receiveShadow position={[0, 0.15, 0]}>
      <sphereGeometry args={[0.15, 16, 16]} />
      <meshStandardMaterial color={color} roughness={0.7} />
    </mesh>
  );
};

interface SceneProps {
  lastSale: { id: number; bread: BreadType; timestamp: number } | null;
  inventory?: Record<string, number>;
  timePhase: TimePhase;
  config: ShopCustomization;
}

export const Bakery3DScene: React.FC<SceneProps> = ({ lastSale, inventory, timePhase, config }) => {
  const [customers, setCustomers] = useState<{ id: number; bread: BreadType }[]>([]);
  useEffect(() => { if (lastSale) setCustomers(prev => [...prev, { id: lastSale.id, bread: lastSale.bread }]); }, [lastSale]);

  const lightColor = timePhase === 'morning' ? '#fff7ed' : timePhase === 'noon' ? '#ffffff' : '#ff9c50';
  const lightIntensity = timePhase === 'morning' ? 0.6 : timePhase === 'noon' ? 1.0 : 0.4;

  const availableBreads = useMemo(() => {
    if (!inventory) return [];
    return Object.keys(inventory).filter(k => inventory[k] > 0).slice(0, 8);
  }, [inventory]);

  return (
    <Canvas shadows camera={{ position: [0, 5, 8], fov: 45 }}>
      <color attach="background" args={['#1a1a1a']} />
      <ambientLight intensity={0.4} color={lightColor} />
      <directionalLight position={[5, 10, 5]} intensity={lightIntensity} castShadow />

      {/* Wall & Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow position={[0, 0, 0]}><planeGeometry args={[20, 20]} /><meshStandardMaterial color={config.floorColor} /></mesh>
      <mesh position={[0, 5, -5]} receiveShadow><planeGeometry args={[20, 10]} /><meshStandardMaterial color={config.wallColor} /></mesh>

      {/* Counter */}
      <group position={[0, 0, 1]}>
        <mesh position={[0, 0.6, 0]} receiveShadow><boxGeometry args={[4.5, 0.1, 1.2]} /><meshStandardMaterial color={config.counterColor} /></mesh>
        <mesh position={[0, 0.3, 0]} receiveShadow><boxGeometry args={[4.3, 0.6, 1.0]} /><meshStandardMaterial color={config.counterColor} roughness={1} /></mesh>
        {availableBreads.slice(0, 4).map((b, i) => (
          <group key={b} position={[(i - 1.5) * 1.0, 0.65, 0.1]}><BreadMesh type={b as BreadType} /></group>
        ))}
      </group>

      {customers.map(c => <Customer key={c.id} id={c.id} breadType={c.bread} onLeave={(id) => setCustomers(p => p.filter(x => x.id !== id))} />)}
      <ContactShadows opacity={0.4} scale={20} blur={2} far={4.5} />
    </Canvas>
  );
};

