import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { ReviewModal } from './components/ReviewModal';
import { LabModal } from './components/LabModal';
import { CustomizeModal } from './components/CustomizeModal';
import { PricingModal } from './components/PricingModal';
import { generateDailyReport, generateEndDayReviews } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission,
  Review,
  TimePhase,
  BreadRecipe,
  CreativeRecipe
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    totalSalesCount: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: { [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100, [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100, [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100, [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100, [IngredientType.FISH]: 100 },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<string, number>),
    customPrices: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: RECIPES[type as keyof typeof RECIPES]?.basePrice || 300 }), {} as Record<string, number>),
    isShopOpen: false,
    bakingStatus: {},
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false,
    reviews: [],
    customization: { wallColor: '#ffffff', floorColor: '#fef3c7', counterColor: '#8b5a2b' },
    timePhase: 'morning',
    creativeRecipes: []
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [modals, setModals] = useState({ upgrades: false, reviews: false, lab: false, customize: false, pricing: false });
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  // Time Phase Logic (Morning -> Noon -> Evening during 30s day)
  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const timer = setTimeout(() => {
      setGameState(prev => ({ ...prev, timePhase: prev.timePhase === 'morning' ? 'noon' : 'evening' }));
    }, 10000);
    return () => clearTimeout(timer);
  }, [gameState.isShopOpen, gameState.timePhase]);

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number) => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(m => {
      if (m.isCleared) return m;
      let nextVal = m.type === 'earn_money' ? currentDailyEarnings : (m.type === type && (!m.targetId || m.targetId === targetId) ? m.currentValue + increment : m.currentValue);
      const isNowCleared = nextVal >= m.targetValue;
      if (isNowCleared) { extraMoney += 50000; addLog(`達成: ${m.description}`); }
      return { ...m, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.every(m => m.isCleared) && !prevMissions.every(m => m.isCleared);
    if (allBonus) { extraMoney += 150000; addLog(`全ミッション達成ボーナス！`); }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const startBaking = (breadId: string) => {
    setGameState(prev => {
      if (prev.bakingStatus[breadId] !== null && prev.bakingStatus[breadId] !== undefined) return prev;
      const recipe = (prev.creativeRecipes.find(r => r.id === breadId) || RECIPES[breadId as keyof typeof RECIPES]) as BreadRecipe | CreativeRecipe;
      if (!recipe) return prev;
      const newIngs = { ...prev.ingredients };
      for (const [ing, amount] of Object.entries(recipe.ingredients)) {
        if (newIngs[ing as IngredientType] < (amount as number)) { addLog(`材料不足: ${INGREDIENTS_DATA[ing as IngredientType].name}`); return prev; }
        newIngs[ing as IngredientType] -= (amount as number);
      }
      return { ...prev, ingredients: newIngs, bakingStatus: { ...prev.bakingStatus, [breadId]: 0 } };
    });
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBaking = { ...prev.bakingStatus };
        const nextInv = { ...prev.inventory };
        let bakedId: string | null = null;
        let bakedCount = 0;
        let changed = false;

        // Using Object.entries ensures the values are paired with keys and helps with inference
        Object.entries(nextBaking).forEach(([id, progress]) => {
          if (progress === null) return;
          const recipe = (prev.creativeRecipes.find(r => r.id === id) || RECIPES[id as keyof typeof RECIPES]) as BreadRecipe | CreativeRecipe;
          if (!recipe) return;

          const speedMod = Math.pow(0.95, prev.upgrades.speed);
          const nextVal = progress + (100 / (recipe.bakeTimeSec * speedMod * 10));
          if (nextVal >= 100) {
            nextBaking[id] = null;
            const count = recipe.batchSize + prev.upgrades.batch;
            nextInv[id] += count;
            bakedId = id; bakedCount = count;
          } else { nextBaking[id] = nextVal; }
          changed = true;
        });

        if (!changed) return prev;
        const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'bake_bread', bakedId!, bakedCount, prev.dailyEarnings);
        return { ...prev, bakingStatus: nextBaking, inventory: nextInv, money: prev.money + reward, currentMissions: missions, allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus };
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const available = Object.keys(prev.inventory).filter(id => prev.inventory[id] > 0);
        if (available.length === 0) return prev;
        const breadId = available[Math.floor(Math.random() * available.length)];
        const recipe = (prev.creativeRecipes.find(r => r.id === breadId) || RECIPES[breadId as keyof typeof RECIPES]) as BreadRecipe | CreativeRecipe;
        if (!recipe) return prev;
        const price = prev.customPrices[breadId] || recipe.basePrice;

        let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
        if (price > recipe.basePrice * 1.5) sellChance *= 0.5;
        if (price < recipe.basePrice * 0.7) sellChance *= 1.5;
        if (dailyEvent?.trend === breadId) sellChance *= 2.0;

        if (Math.random() < sellChance * prev.upgrades.branches * (dailyEvent?.salesModifier || 1.0)) {
          const nextEarnings = prev.dailyEarnings + price;
          const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'sell_bread', breadId, 1, nextEarnings);
          if (breadId in BreadType) setLastSale({ id: Date.now(), bread: breadId as BreadType, timestamp: Date.now() });
          return { ...prev, money: prev.money + price + reward, dailyEarnings: nextEarnings, inventory: { ...prev.inventory, [breadId]: prev.inventory[breadId] - 1 }, levelProgressSales: prev.levelProgressSales + 1, currentMissions: missions, allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus };
        }
        return prev;
      });
    }, 1000);
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const finishDay = async () => {
    const reviews = await generateEndDayReviews(gameState.levelProgressSales, gameState.dailyEarnings, Object.values(gameState.inventory).reduce((a, b) => a + b, 0), dailyEvent?.weather || "晴れ");
    setGameState(prev => ({ ...prev, isShopOpen: false, reviews }));
    setModals({ ...modals, reviews: true });
  };

  const prepareDay = async (day: number) => {
    setLoadingDaily(true);
    const event = await generateDailyReport(day, gameState.shopLevel);
    setDailyEvent(event);
    setGameState(prev => ({ ...prev, day, dailyEarnings: 0, timePhase: 'morning', currentMissions: event.missions }));
    setLoadingDaily(false);
  };

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center animate-pulse"><Icons.Wheat className="w-16 h-16 text-amber-500 mb-4" /><h2 className="text-xl font-bold text-amber-900">朝の仕込み中...</h2></div>}

      {dailyEvent && !gameState.isShopOpen && <DailyModal event={dailyEvent} onClose={() => setGameState(p => ({ ...p, isShopOpen: true }))} />}
      {modals.upgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={(k, c) => setGameState(p => ({ ...p, money: p.money - c, upgrades: { ...p.upgrades, [k]: p.upgrades[k] + 1 } }))} onClose={() => setModals({ ...modals, upgrades: false })} />}
      {modals.reviews && <ReviewModal reviews={gameState.reviews} onClose={() => setModals({ ...modals, reviews: false })} />}
      {modals.lab && <LabModal currentMoney={gameState.money} ingredients={gameState.ingredients} onDevelop={(r) => setGameState(p => ({ ...p, creativeRecipes: [...p.creativeRecipes, r], inventory: { ...p.inventory, [r.id]: 0 }, customPrices: { ...p.customPrices, [r.id]: r.basePrice } }))} onClose={() => setModals({ ...modals, lab: false })} />}
      {modals.customize && <CustomizeModal currentConfig={gameState.customization} onUpdate={(c) => setGameState(p => ({ ...p, customization: c }))} onClose={() => setModals({ ...modals, customize: false })} />}
      {modals.pricing && <PricingModal recipes={[...Object.values(RECIPES), ...gameState.creativeRecipes]} currentPrices={gameState.customPrices} onUpdate={(id, p) => setGameState(s => ({ ...s, customPrices: { ...s.customPrices, [id]: p } }))} onClose={() => setModals({ ...modals, pricing: false })} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 px-4 py-3 flex justify-between items-center">
        <div className="flex items-center gap-2"><div className="bg-amber-500 p-2 rounded-lg text-white"><Icons.Store className="w-5 h-5" /></div><h1 className="font-bold text-amber-900">小麦の詩</h1></div>
        <div className="flex items-center gap-3">
          <div className="text-xs bg-amber-100 px-3 py-1 rounded-full font-bold">{gameState.day}日目・{gameState.timePhase === 'morning' ? '朝' : gameState.timePhase === 'noon' ? '昼' : '夕'}</div>
          <div className="text-sm font-bold text-amber-800">¥{gameState.money.toLocaleString()}</div>
          <button onClick={() => setModals({ ...modals, pricing: true })} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Tag className="w-4 h-4 text-stone-600" /></button>
          <button onClick={() => setModals({ ...modals, customize: true })} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Palette className="w-4 h-4 text-stone-600" /></button>
          <button onClick={() => setModals({ ...modals, upgrades: true })} className="p-2 bg-amber-500 text-white rounded-full"><Icons.Hammer className="w-4 h-4" /></button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
          <section className="bg-white rounded-2xl p-5 border border-amber-100">
            <div className="flex justify-between items-center mb-4"><h2 className="text-lg font-bold flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2><button onClick={() => setModals({ ...modals, lab: true })} className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-1 rounded-lg border border-indigo-100 font-bold">新メニュー開発</button></div>
            <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
              {[...Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel), ...gameState.creativeRecipes].map(recipe => (
                <div key={recipe.id} className="border border-stone-100 rounded-xl p-4 bg-stone-50">
                  <div className="flex justify-between mb-2"><h3 className="font-bold text-sm text-stone-800">{recipe.name}</h3><span className="text-[10px] font-bold text-amber-600">¥{(gameState.customPrices[recipe.id] || recipe.basePrice).toLocaleString()}</span></div>
                  {gameState.bakingStatus[recipe.id] !== undefined && gameState.bakingStatus[recipe.id] !== null ? (
                    <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden"><div className="bg-amber-500 h-full transition-all" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}></div></div>
                  ) : (
                    <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-white border border-stone-200 text-[10px] font-bold rounded-lg hover:bg-amber-50">仕込む</button>
                  )}
                </div>
              ))}
            </div>
          </section>
        </div>

        <div className="space-y-6">
          <section className="bg-stone-900 rounded-2xl p-1 shadow-2xl overflow-hidden aspect-video">
            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} timePhase={gameState.timePhase} config={gameState.customization} />
          </section>

          <section className="bg-white rounded-2xl p-5 border border-amber-200">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" />ミッション</h2>
            <div className="space-y-3">
              {gameState.currentMissions.map(m => (
                <div key={m.id} className={`p-3 rounded-xl border text-xs ${m.isCleared ? 'bg-green-50 border-green-200 text-green-700' : 'bg-stone-50 border-stone-100 text-stone-600'}`}>
                  {m.description} ({m.currentValue}/{m.targetValue})
                </div>
              ))}
            </div>
            <div className="mt-6 flex flex-col gap-2">
              {gameState.isShopOpen ? (
                <button onClick={finishDay} className="w-full py-3 bg-red-500 text-white font-bold rounded-xl shadow-lg animate-pulse">営業終了</button>
              ) : (
                <button onClick={() => prepareDay(gameState.day + 1)} className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl">翌日の準備へ</button>
              )}
            </div>
          </section>
        </div>

        <div className="space-y-6">
          <section className="bg-white rounded-2xl p-5 border border-amber-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />材料在庫</h2>
            <div className="grid grid-cols-1 gap-2 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.values(INGREDIENTS_DATA).map(item => (
                <div key={item.id} className="p-3 border rounded-xl flex justify-between items-center text-xs">
                  <span>{item.name}: {gameState.ingredients[item.id]}{item.unit}</span>
                  <button onClick={() => setGameState(p => ({ ...p, money: p.money - item.cost, ingredients: { ...p.ingredients, [item.id]: p.ingredients[item.id] + 10 } }))} disabled={gameState.money < item.cost} className="bg-amber-500 text-white px-2 py-1 rounded">購入</button>
                </div>
              ))}
            </div>
          </section>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum IngredientType {
  FLOUR = 'flour',
  SUGAR = 'sugar',
  BUTTER = 'butter',
  YEAST = 'yeast',
  MILK = 'milk',
  EGGS = 'eggs',
  SALT = 'salt',
  CHOCO = 'choco',
  ANKO = 'anko',
  CURRY = 'curry',
  VEGETABLES = 'vegetables',
  MEAT = 'meat',
  FISH = 'fish'
}

export enum BreadType {
  SHOKUPAN = 'shokupan',
  ANPAN = 'anpan',
  CREAMPAN = 'creampan',
  SHIOPAN = 'shiopan',
  MELONPAN = 'melonpan',
  CURRYPAN = 'currypan',
  CORNET = 'cornet',
  BAGUETTE = 'baguette',
  BAGEL = 'bagel',
  EPI = 'epi',
  CROISSANT = 'croissant',
  CINNAMON = 'cinnamon',
  FOCACCIA = 'focaccia',
  PRETZEL = 'pretzel',
  DANISH = 'danish',
  BRIOCHE = 'brioche',
  RYE = 'rye',
  SOURDOUGH = 'sourdough',
  PANETTONE = 'panettone',
  SANDWICH = 'sandwich',
  TUNAPAN = 'tunapan',
  MEATPIE = 'meatpie'
}

export interface DailyMission {
  id: string;
  description: string;
  targetValue: number;
  currentValue: number;
  type: 'sell_bread' | 'bake_bread' | 'earn_money' | 'buy_ingredient';
  targetId?: string; // BreadType or IngredientType
  isCleared: boolean;
}

export interface Ingredient {
  id: IngredientType;
  name: string;
  cost: number;
  stock: number;
  unit: string;
}

export interface BreadRecipe {
  id: BreadType;
  name: string;
  description: string;
  basePrice: number;
  ingredients: { [key in IngredientType]?: number };
  batchSize: number;
  levelRequired: number;
  bakeTimeSec: number;
}

export interface DailyEvent {
  day: number;
  weather: string;
  trend: BreadType | null;
  trendReason: string;
  customerSentiment: string;
  salesModifier: number;
  costModifier: number;
  missions: DailyMission[];
}

export interface UpgradeStats {
  speed: number;
  batch: number;
  promo: number;
  branches: number;
  eatIn: number;
  staff: number; // New: Number of hired staff
}

export interface GameState {
  money: number;
  day: number;
  dailyEarnings: number;
  reputation: number;
  shopLevel: number;
  levelProgressSales: number;
  ingredients: Record<IngredientType, number>;
  ingredientLimits: Record<IngredientType, number>; // New: Inventory limits
  inventory: Record<BreadType, number>;
  isShopOpen: boolean;
  bakingStatus: Record<BreadType, number | null>;
  upgrades: UpgradeStats;
  currentMissions: DailyMission[];
  allMissionsBonusClaimed: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100,
      [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100,
      [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100,
      [IngredientType.FISH]: 100,
    },
    ingredientLimits: {
      [IngredientType.FLOUR]: 200, [IngredientType.SUGAR]: 200, [IngredientType.BUTTER]: 200,
      [IngredientType.YEAST]: 200, [IngredientType.MILK]: 200, [IngredientType.EGGS]: 200,
      [IngredientType.SALT]: 200, [IngredientType.CHOCO]: 200, [IngredientType.ANKO]: 200,
      [IngredientType.CURRY]: 200, [IngredientType.VEGETABLES]: 200, [IngredientType.MEAT]: 200,
      [IngredientType.FISH]: 200,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;
      let nextVal = mission.type === 'earn_money' ? currentDailyEarnings : (mission.type === type && (!mission.targetId || mission.targetId === targetId) ? mission.currentValue + increment : mission.currentValue);
      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared);
    if (allBonus) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
    }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);

    setGameState(prev => {
      const currentStock = prev.ingredients[type];
      const limit = prev.ingredientLimits[type];
      const possibleAmount = Math.min(amount, limit - currentStock);

      if (possibleAmount <= 0) {
        addLog(`仕入れ不可: ${item.name} は在庫上限 (${limit}${item.unit}) に達しています`);
        return prev;
      }

      const totalCost = unitCost * possibleAmount;
      if (prev.money < totalCost) {
        addLog(`資金不足: ${item.name} ${possibleAmount}個 分の資金が足りません`);
        return prev;
      }

      const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, possibleAmount, prev.dailyEarnings);
      addLog(`仕入れ: ${item.name} を${possibleAmount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      return {
        ...prev,
        money: prev.money - totalCost + reward,
        ingredients: { ...prev.ingredients, [type]: currentStock + possibleAmount },
        currentMissions: missions,
        allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
      };
    });
  };

  const restockAllToLimit = () => {
    setGameState(prev => {
      let totalCost = 0;
      const newIngredients = { ...prev.ingredients };
      const costModifier = dailyEvent?.costModifier || 1.0;
      let purchasedCount = 0;

      Object.values(IngredientType).forEach(type => {
        const item = INGREDIENTS_DATA[type];
        const limit = prev.ingredientLimits[type];
        const current = prev.ingredients[type];
        const need = Math.max(0, limit - current);
        if (need > 0) {
          const cost = Math.floor(item.cost * costModifier) * need;
          if (prev.money >= totalCost + cost) {
            totalCost += cost;
            newIngredients[type] += need;
            purchasedCount++;
          }
        }
      });

      if (purchasedCount === 0) {
        addLog("一括仕入れ: 補充が必要な材料がないか、資金が足りません");
        return prev;
      }

      addLog(`一括仕入れ: 全材料を上限まで補充しました (-¥${totalCost.toLocaleString()})`);
      return { ...prev, money: prev.money - totalCost, ingredients: newIngredients };
    });
  };

  const updateLimit = (type: IngredientType, delta: number) => {
    setGameState(prev => ({
      ...prev,
      ingredientLimits: {
        ...prev.ingredientLimits,
        [type]: Math.max(0, prev.ingredientLimits[type] + delta)
      }
    }));
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({ ...prev, money: prev.money - cost, upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 } }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) { canBake = false; return prev; }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false; return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) { newIngredients[ingKey as IngredientType] -= (amount || 0); }
      return { ...prev, ingredients: newIngredients, bakingStatus: { ...prev.bakingStatus, [breadType]: 0 } };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff = gameState.upgrades.staff - currentBakingCount;
      if (availableStaff <= 0) return;
      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && gameState.inventory[type] < 5 && gameState.bakingStatus[type] === null;
      });
      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;
        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;
            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount; bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else { nextBakingStatus[breadType] = newProgress; }
            changed = true;
          }
        });
        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;
            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions; totalReward += reward; if (allBonus) finalAllBonus = true;
            }
            return { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory, currentMissions: nextMissions, money: prev.money + totalReward, allMissionsBonusClaimed: finalAllBonus };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];
        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) { sellChance *= dailyEvent.salesModifier; if (dailyEvent.trend === breadToSell) sellChance *= 1.5; }
            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price; salesCountTotal += 1; currentInventory[breadToSell] -= 1; lastSoldBread = breadToSell;
                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }
        if (moneyEarned === 0) return prev;
        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);
        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions; totalReward += result.reward; if (result.allBonus) allBonus = true;
        });
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return { ...prev, money: prev.money + moneyEarned + totalReward, dailyEarnings: nextDailyEarnings, reputation: prev.reputation + 0.1, levelProgressSales: prev.levelProgressSales + salesCountTotal, inventory: currentInventory, currentMissions: nextMissions, allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0, money: prev.money - wages }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };
  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}
      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg text-nowrap">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800 text-sm">{recipe.name}</h3>
                            </div>
                            <div className="flex flex-wrap gap-1 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[9px] px-1.5 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden"><div className="bg-amber-500 h-full relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg text-xs shadow-sm">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 relative">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 目標</h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-[10px] font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-3 h-3 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1 overflow-hidden">
                                <div className={`h-full ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-[10px] font-bold text-amber-800">ランク: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">進捗: {gameState.levelProgressSales}個</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-2"><div className="bg-orange-500 h-full rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="w-full py-1 bg-orange-500 text-white text-[10px] font-bold rounded animate-pulse">ランクUP！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl text-xs border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 text-sm transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                  <button onClick={restockAllToLimit} className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold px-2 py-1 rounded-lg border border-amber-200 transition-colors">
                    上限まで一括仕入れ
                  </button>
                </div>
                <div className="space-y-3 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const current = gameState.ingredients[item.id];
                        const limit = gameState.ingredientLimits[item.id];
                        const progress = Math.min(100, (current / limit) * 100);
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        const isFull = current >= limit;

                        return (
                            <div key={item.id} className="p-3 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="flex items-center gap-2">
                                      <div className="font-bold text-stone-700 text-xs">{item.name}</div>
                                      <div className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${isFull ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {current} / {limit}{item.unit}
                                      </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                      <button onClick={() => updateLimit(item.id, -50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">-</button>
                                      <div className="text-[9px] font-bold text-stone-400">上限</div>
                                      <button onClick={() => updateLimit(item.id, 50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">+</button>
                                    </div>
                                </div>
                                <div className="w-full bg-stone-200 h-1 rounded-full overflow-hidden mb-2">
                                  <div className={`h-full transition-all duration-500 ${isFull ? 'bg-orange-500' : 'bg-blue-500'}`} style={{ width: `${progress}%` }}></div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button 
                                          key={amount} 
                                          onClick={() => buyIngredient(item.id, amount)} 
                                          disabled={isFull || gameState.money < (unitCost * amount)} 
                                          className={`py-1 rounded text-[9px] font-bold flex flex-col items-center border transition-all 
                                            ${!isFull && gameState.money >= (unitCost * amount) 
                                              ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' 
                                              : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}`}
                                        >
                                            <span className="opacity-60">x{amount}</span>
                                            <span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100,
      [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100,
      [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100,
      [IngredientType.FISH]: 100,
    },
    ingredientLimits: {
      [IngredientType.FLOUR]: 200, [IngredientType.SUGAR]: 200, [IngredientType.BUTTER]: 200,
      [IngredientType.YEAST]: 200, [IngredientType.MILK]: 200, [IngredientType.EGGS]: 200,
      [IngredientType.SALT]: 200, [IngredientType.CHOCO]: 200, [IngredientType.ANKO]: 200,
      [IngredientType.CURRY]: 200, [IngredientType.VEGETABLES]: 200, [IngredientType.MEAT]: 200,
      [IngredientType.FISH]: 200,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;
      let nextVal = mission.type === 'earn_money' ? currentDailyEarnings : (mission.type === type && (!mission.targetId || mission.targetId === targetId) ? mission.currentValue + increment : mission.currentValue);
      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared);
    if (allBonus) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
    }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);

    setGameState(prev => {
      const currentStock = prev.ingredients[type];
      const limit = prev.ingredientLimits[type];
      const possibleAmount = Math.min(amount, limit - currentStock);

      if (possibleAmount <= 0) {
        addLog(`仕入れ不可: ${item.name} は在庫上限 (${limit}${item.unit}) に達しています`);
        return prev;
      }

      const totalCost = unitCost * possibleAmount;
      if (prev.money < totalCost) {
        addLog(`資金不足: ${item.name} ${possibleAmount}個 分の資金が足りません`);
        return prev;
      }

      const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, possibleAmount, prev.dailyEarnings);
      addLog(`仕入れ: ${item.name} を${possibleAmount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      return {
        ...prev,
        money: prev.money - totalCost + reward,
        ingredients: { ...prev.ingredients, [type]: currentStock + possibleAmount },
        currentMissions: missions,
        allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
      };
    });
  };

  const restockAllToLimit = () => {
    setGameState(prev => {
      let totalCost = 0;
      const newIngredients = { ...prev.ingredients };
      const costModifier = dailyEvent?.costModifier || 1.0;
      let purchasedCount = 0;

      Object.values(IngredientType).forEach(type => {
        const item = INGREDIENTS_DATA[type];
        const limit = prev.ingredientLimits[type];
        const current = prev.ingredients[type];
        const need = Math.max(0, limit - current);
        if (need > 0) {
          const cost = Math.floor(item.cost * costModifier) * need;
          if (prev.money >= totalCost + cost) {
            totalCost += cost;
            newIngredients[type] += need;
            purchasedCount++;
          }
        }
      });

      if (purchasedCount === 0) {
        addLog("一括仕入れ: 補充が必要な材料がないか、資金が足りません");
        return prev;
      }

      addLog(`一括仕入れ: 全材料を上限まで補充しました (-¥${totalCost.toLocaleString()})`);
      return { ...prev, money: prev.money - totalCost, ingredients: newIngredients };
    });
  };

  const updateLimit = (type: IngredientType, delta: number) => {
    setGameState(prev => ({
      ...prev,
      ingredientLimits: {
        ...prev.ingredientLimits,
        [type]: Math.max(0, prev.ingredientLimits[type] + delta)
      }
    }));
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({ ...prev, money: prev.money - cost, upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 } }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) { canBake = false; return prev; }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false; return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) { newIngredients[ingKey as IngredientType] -= (amount || 0); }
      return { ...prev, ingredients: newIngredients, bakingStatus: { ...prev.bakingStatus, [breadType]: 0 } };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff = gameState.upgrades.staff - currentBakingCount;
      if (availableStaff <= 0) return;
      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && gameState.inventory[type] < 5 && gameState.bakingStatus[type] === null;
      });
      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;
        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;
            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount; bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else { nextBakingStatus[breadType] = newProgress; }
            changed = true;
          }
        });
        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;
            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions; totalReward += reward; if (allBonus) finalAllBonus = true;
            }
            return { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory, currentMissions: nextMissions, money: prev.money + totalReward, allMissionsBonusClaimed: finalAllBonus };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];
        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) { sellChance *= dailyEvent.salesModifier; if (dailyEvent.trend === breadToSell) sellChance *= 1.5; }
            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price; salesCountTotal += 1; currentInventory[breadToSell] -= 1; lastSoldBread = breadToSell;
                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }
        if (moneyEarned === 0) return prev;
        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);
        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions; totalReward += result.reward; if (result.allBonus) allBonus = true;
        });
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return { ...prev, money: prev.money + moneyEarned + totalReward, dailyEarnings: nextDailyEarnings, reputation: prev.reputation + 0.1, levelProgressSales: prev.levelProgressSales + salesCountTotal, inventory: currentInventory, currentMissions: nextMissions, allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0, money: prev.money - wages }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };
  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}
      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg text-nowrap">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800 text-sm">{recipe.name}</h3>
                                <div className="bg-amber-100 px-2 py-0.5 rounded text-[10px] font-bold text-amber-700">在庫: {gameState.inventory[recipe.id]}</div>
                            </div>
                            <div className="flex flex-wrap gap-1 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[9px] px-1.5 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden"><div className="bg-amber-500 h-full relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg text-xs shadow-sm">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />ショーケース（在庫状況）</h2>
                <div className="grid grid-cols-2 gap-3 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                  {Object.entries(gameState.inventory).map(([type, count]) => {
                    if (count <= 0) return null;
                    const bread = RECIPES[type as BreadType];
                    return (
                      <div key={type} className="bg-orange-50 border border-orange-100 rounded-xl p-3 flex flex-col items-center text-center transition-all hover:shadow-md">
                        <span className="text-[10px] font-bold text-orange-800 mb-1 leading-tight">{bread.name}</span>
                        <div className="flex items-baseline gap-1">
                          <span className="text-lg font-bold text-orange-900">{count}</span>
                          <span className="text-[10px] text-orange-600">個</span>
                        </div>
                      </div>
                    );
                  })}
                  {Object.values(gameState.inventory).every(c => c === 0) && (
                    <div className="col-span-2 py-8 text-center text-stone-400 text-xs italic">
                      現在、在庫はありません。<br/>パンを焼きましょう！
                    </div>
                  )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 relative">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 目標</h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-[10px] font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-3 h-3 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1 overflow-hidden">
                                <div className={`h-full ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-[10px] font-bold text-amber-800">ランク: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">進捗: {gameState.levelProgressSales}個</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-2"><div className="bg-orange-500 h-full rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="w-full py-1 bg-orange-500 text-white text-[10px] font-bold rounded animate-pulse">ランクUP！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl text-xs border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 text-sm transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                  <button onClick={restockAllToLimit} className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold px-2 py-1 rounded-lg border border-amber-200 transition-colors">
                    上限まで一括仕入れ
                  </button>
                </div>
                <div className="space-y-3 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const current = gameState.ingredients[item.id];
                        const limit = gameState.ingredientLimits[item.id];
                        const progress = Math.min(100, (current / limit) * 100);
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        const isFull = current >= limit;

                        return (
                            <div key={item.id} className="p-3 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="flex items-center gap-2">
                                      <div className="font-bold text-stone-700 text-xs">{item.name}</div>
                                      <div className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${isFull ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {current} / {limit}{item.unit}
                                      </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                      <button onClick={() => updateLimit(item.id, -50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">-</button>
                                      <div className="text-[9px] font-bold text-stone-400">上限</div>
                                      <button onClick={() => updateLimit(item.id, 50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">+</button>
                                    </div>
                                </div>
                                <div className="w-full bg-stone-200 h-1 rounded-full overflow-hidden mb-2">
                                  <div className={`h-full transition-all duration-500 ${isFull ? 'bg-orange-500' : 'bg-blue-500'}`} style={{ width: `${progress}%` }}></div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button 
                                          key={amount} 
                                          onClick={() => buyIngredient(item.id, amount)} 
                                          disabled={isFull || gameState.money < (unitCost * amount)} 
                                          className={`py-1 rounded text-[9px] font-bold flex flex-col items-center border transition-all 
                                            ${!isFull && gameState.money >= (unitCost * amount) 
                                              ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' 
                                              : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}`}
                                        >
                                            <span className="opacity-60">x{amount}</span>
                                            <span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100,
      [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100,
      [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100,
      [IngredientType.FISH]: 100,
    },
    ingredientLimits: {
      [IngredientType.FLOUR]: 200, [IngredientType.SUGAR]: 200, [IngredientType.BUTTER]: 200,
      [IngredientType.YEAST]: 200, [IngredientType.MILK]: 200, [IngredientType.EGGS]: 200,
      [IngredientType.SALT]: 200, [IngredientType.CHOCO]: 200, [IngredientType.ANKO]: 200,
      [IngredientType.CURRY]: 200, [IngredientType.VEGETABLES]: 200, [IngredientType.MEAT]: 200,
      [IngredientType.FISH]: 200,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;
      let nextVal = mission.type === 'earn_money' ? currentDailyEarnings : (mission.type === type && (!mission.targetId || mission.targetId === targetId) ? mission.currentValue + increment : mission.currentValue);
      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared);
    if (allBonus) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
    }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);

    setGameState(prev => {
      const currentStock = prev.ingredients[type];
      const limit = prev.ingredientLimits[type];
      const possibleAmount = Math.min(amount, limit - currentStock);

      if (possibleAmount <= 0) {
        addLog(`仕入れ不可: ${item.name} は在庫上限 (${limit}${item.unit}) に達しています`);
        return prev;
      }

      const totalCost = unitCost * possibleAmount;
      if (prev.money < totalCost) {
        addLog(`資金不足: ${item.name} ${possibleAmount}個 分の資金が足りません`);
        return prev;
      }

      const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, possibleAmount, prev.dailyEarnings);
      addLog(`仕入れ: ${item.name} を${possibleAmount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      return {
        ...prev,
        money: prev.money - totalCost + reward,
        ingredients: { ...prev.ingredients, [type]: currentStock + possibleAmount },
        currentMissions: missions,
        allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
      };
    });
  };

  const restockAllToLimit = () => {
    setGameState(prev => {
      let totalCost = 0;
      const newIngredients = { ...prev.ingredients };
      const costModifier = dailyEvent?.costModifier || 1.0;
      let purchasedCount = 0;

      Object.values(IngredientType).forEach(type => {
        const item = INGREDIENTS_DATA[type];
        const limit = prev.ingredientLimits[type];
        const current = prev.ingredients[type];
        const need = Math.max(0, limit - current);
        if (need > 0) {
          const cost = Math.floor(item.cost * costModifier) * need;
          if (prev.money >= totalCost + cost) {
            totalCost += cost;
            newIngredients[type] += need;
            purchasedCount++;
          }
        }
      });

      if (purchasedCount === 0) {
        addLog("一括仕入れ: 補充が必要な材料がないか、資金が足りません");
        return prev;
      }

      addLog(`一括仕入れ: 全材料を上限まで補充しました (-¥${totalCost.toLocaleString()})`);
      return { ...prev, money: prev.money - totalCost, ingredients: newIngredients };
    });
  };

  const updateLimit = (type: IngredientType, delta: number) => {
    setGameState(prev => ({
      ...prev,
      ingredientLimits: {
        ...prev.ingredientLimits,
        [type]: Math.max(0, prev.ingredientLimits[type] + delta)
      }
    }));
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({ ...prev, money: prev.money - cost, upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 } }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) { canBake = false; return prev; }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false; return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) { newIngredients[ingKey as IngredientType] -= (amount || 0); }
      return { ...prev, ingredients: newIngredients, bakingStatus: { ...prev.bakingStatus, [breadType]: 0 } };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      // Fix: Casting staff upgrade level to number to ensure the arithmetic result is treated as a number
      const availableStaff: number = (gameState.upgrades.staff as number) - currentBakingCount;
      if (availableStaff <= 0) return;
      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && gameState.inventory[type] < 5 && gameState.bakingStatus[type] === null;
      });
      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;
        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;
            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount; bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else { nextBakingStatus[breadType] = newProgress; }
            changed = true;
          }
        });
        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;
            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions; totalReward += reward; if (allBonus) finalAllBonus = true;
            }
            return { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory, currentMissions: nextMissions, money: prev.money + totalReward, allMissionsBonusClaimed: finalAllBonus };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let salesCountTotal = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];
        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) { sellChance *= dailyEvent.salesModifier; if (dailyEvent.trend === breadToSell) sellChance *= 1.5; }
            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);
                moneyEarned += price; salesCountTotal += 1; currentInventory[breadToSell] -= 1; lastSoldBread = breadToSell;
                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }
        if (moneyEarned === 0) return prev;
        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);
        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions; totalReward += result.reward; if (result.allBonus) allBonus = true;
        });
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return { ...prev, money: prev.money + moneyEarned + totalReward, dailyEarnings: nextDailyEarnings, reputation: prev.reputation + 0.1, levelProgressSales: prev.levelProgressSales + salesCountTotal, inventory: currentInventory, currentMissions: nextMissions, allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0, money: prev.money - wages }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };
  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}
      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg text-nowrap">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800 text-sm">{recipe.name}</h3>
                                <div className="bg-amber-100 px-2 py-0.5 rounded text-[10px] font-bold text-amber-700">在庫: {gameState.inventory[recipe.id]}</div>
                            </div>
                            <div className="flex flex-wrap gap-1 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[9px] px-1.5 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden"><div className="bg-amber-500 h-full relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg text-xs shadow-sm">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />ショーケース（在庫状況）</h2>
                <div className="grid grid-cols-2 gap-3 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                  {Object.entries(gameState.inventory).map(([type, count]) => {
                    if (count <= 0) return null;
                    const bread = RECIPES[type as BreadType];
                    return (
                      <div key={type} className="bg-orange-50 border border-orange-100 rounded-xl p-3 flex flex-col items-center text-center transition-all hover:shadow-md">
                        <span className="text-[10px] font-bold text-orange-800 mb-1 leading-tight">{bread.name}</span>
                        <div className="flex items-baseline gap-1">
                          <span className="text-lg font-bold text-orange-900">{count}</span>
                          <span className="text-[10px] text-orange-600">個</span>
                        </div>
                      </div>
                    );
                  })}
                  {Object.values(gameState.inventory).every(c => c === 0) && (
                    <div className="col-span-2 py-8 text-center text-stone-400 text-xs italic">
                      現在、在庫はありません。<br/>パンを焼きましょう！
                    </div>
                  )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 relative">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 目標</h2>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-[10px] font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-3 h-3 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1 overflow-hidden">
                                <div className={`h-full ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-[10px] font-bold text-amber-800">ランク: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">進捗: {gameState.levelProgressSales}個</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-2"><div className="bg-orange-500 h-full rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={() => setGameState(prev => ({...prev, shopLevel: prev.shopLevel + 1, levelProgressSales: 0}))} className="w-full py-1 bg-orange-500 text-white text-[10px] font-bold rounded animate-pulse">ランクUP！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl text-xs border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 text-sm transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                  <button onClick={restockAllToLimit} className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold px-2 py-1 rounded-lg border border-amber-200 transition-colors">
                    上限まで一括仕入れ
                  </button>
                </div>
                <div className="space-y-3 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const current = gameState.ingredients[item.id];
                        const limit = gameState.ingredientLimits[item.id];
                        const progress = Math.min(100, (current / limit) * 100);
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        const isFull = current >= limit;

                        return (
                            <div key={item.id} className="p-3 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="flex items-center gap-2">
                                      <div className="font-bold text-stone-700 text-xs">{item.name}</div>
                                      <div className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${isFull ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {current} / {limit}{item.unit}
                                      </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                      <button onClick={() => updateLimit(item.id, -50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">-</button>
                                      <div className="text-[9px] font-bold text-stone-400">上限</div>
                                      <button onClick={() => updateLimit(item.id, 50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">+</button>
                                    </div>
                                </div>
                                <div className="w-full bg-stone-200 h-1 rounded-full overflow-hidden mb-2">
                                  <div className={`h-full transition-all duration-500 ${isFull ? 'bg-orange-500' : 'bg-blue-500'}`} style={{ width: `${progress}%` }}></div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button 
                                          key={amount} 
                                          onClick={() => buyIngredient(item.id, amount)} 
                                          disabled={isFull || gameState.money < (unitCost * amount)} 
                                          className={`py-1 rounded text-[9px] font-bold flex flex-col items-center border transition-all 
                                            ${!isFull && gameState.money >= (unitCost * amount) 
                                              ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' 
                                              : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}`}
                                        >
                                            <span className="opacity-60">x{amount}</span>
                                            <span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum IngredientType {
  FLOUR = 'flour',
  SUGAR = 'sugar',
  BUTTER = 'butter',
  YEAST = 'yeast',
  MILK = 'milk',
  EGGS = 'eggs',
  SALT = 'salt',
  CHOCO = 'choco',
  ANKO = 'anko',
  CURRY = 'curry',
  VEGETABLES = 'vegetables',
  MEAT = 'meat',
  FISH = 'fish'
}

export enum BreadType {
  SHOKUPAN = 'shokupan',
  ANPAN = 'anpan',
  CREAMPAN = 'creampan',
  SHIOPAN = 'shiopan',
  MELONPAN = 'melonpan',
  CURRYPAN = 'currypan',
  CORNET = 'cornet',
  BAGUETTE = 'baguette',
  BAGEL = 'bagel',
  EPI = 'epi',
  CROISSANT = 'croissant',
  CINNAMON = 'cinnamon',
  FOCACCIA = 'focaccia',
  PRETZEL = 'pretzel',
  DANISH = 'danish',
  BRIOCHE = 'brioche',
  RYE = 'rye',
  SOURDOUGH = 'sourdough',
  PANETTONE = 'panettone',
  SANDWICH = 'sandwich',
  TUNAPAN = 'tunapan',
  MEATPIE = 'meatpie'
}

export interface DailyMission {
  id: string;
  description: string;
  targetValue: number;
  currentValue: number;
  type: 'sell_bread' | 'bake_bread' | 'earn_money' | 'buy_ingredient';
  targetId?: string; // BreadType or IngredientType
  isCleared: boolean;
}

export interface Ingredient {
  id: IngredientType;
  name: string;
  cost: number;
  stock: number;
  unit: string;
}

export interface BreadRecipe {
  id: BreadType;
  name: string;
  description: string;
  basePrice: number;
  ingredients: { [key in IngredientType]?: number };
  batchSize: number;
  levelRequired: number;
  bakeTimeSec: number;
}

export interface DailyEvent {
  day: number;
  weather: string;
  trend: BreadType | null;
  trendReason: string;
  customerSentiment: string;
  salesModifier: number;
  costModifier: number;
  missions: DailyMission[];
}

export interface UpgradeStats {
  speed: number;
  batch: number;
  promo: number;
  branches: number;
  eatIn: number;
  staff: number;
  brand: number; // New: Brand power for faster leveling
}

export interface GameState {
  money: number;
  day: number;
  dailyEarnings: number;
  reputation: number;
  shopLevel: number;
  levelProgressSales: number;
  ingredients: Record<IngredientType, number>;
  ingredientLimits: Record<IngredientType, number>; // New: Inventory limits
  inventory: Record<BreadType, number>;
  isShopOpen: boolean;
  bakingStatus: Record<BreadType, number | null>;
  upgrades: UpgradeStats;
  currentMissions: DailyMission[];
  allMissionsBonusClaimed: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100,
      [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100,
      [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100,
      [IngredientType.FISH]: 100,
    },
    ingredientLimits: {
      [IngredientType.FLOUR]: 200, [IngredientType.SUGAR]: 200, [IngredientType.BUTTER]: 200,
      [IngredientType.YEAST]: 200, [IngredientType.MILK]: 200, [IngredientType.EGGS]: 200,
      [IngredientType.SALT]: 200, [IngredientType.CHOCO]: 200, [IngredientType.ANKO]: 200,
      [IngredientType.CURRY]: 200, [IngredientType.VEGETABLES]: 200, [IngredientType.MEAT]: 200,
      [IngredientType.FISH]: 200,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0, brand: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;
      let nextVal = mission.type === 'earn_money' ? currentDailyEarnings : (mission.type === type && (!mission.targetId || mission.targetId === targetId) ? mission.currentValue + increment : mission.currentValue);
      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared);
    if (allBonus) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
    }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);

    setGameState(prev => {
      const currentStock = prev.ingredients[type];
      const limit = prev.ingredientLimits[type];
      const possibleAmount = Math.min(amount, limit - currentStock);

      if (possibleAmount <= 0) {
        addLog(`仕入れ不可: ${item.name} は在庫上限 (${limit}${item.unit}) に達しています`);
        return prev;
      }

      const totalCost = unitCost * possibleAmount;
      if (prev.money < totalCost) {
        addLog(`資金不足: ${item.name} ${possibleAmount}個 分の資金が足りません`);
        return prev;
      }

      const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, possibleAmount, prev.dailyEarnings);
      addLog(`仕入れ: ${item.name} を${possibleAmount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      return {
        ...prev,
        money: prev.money - totalCost + reward,
        ingredients: { ...prev.ingredients, [type]: currentStock + possibleAmount },
        currentMissions: missions,
        allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
      };
    });
  };

  const restockAllToLimit = () => {
    setGameState(prev => {
      let totalCost = 0;
      const newIngredients = { ...prev.ingredients };
      const costModifier = dailyEvent?.costModifier || 1.0;
      let purchasedCount = 0;

      Object.values(IngredientType).forEach(type => {
        const item = INGREDIENTS_DATA[type];
        const limit = prev.ingredientLimits[type];
        const current = prev.ingredients[type];
        const need = Math.max(0, limit - current);
        if (need > 0) {
          const cost = Math.floor(item.cost * costModifier) * need;
          if (prev.money >= totalCost + cost) {
            totalCost += cost;
            newIngredients[type] += need;
            purchasedCount++;
          }
        }
      });

      if (purchasedCount === 0) {
        addLog("一括仕入れ: 補充が必要な材料がないか、資金が足りません");
        return prev;
      }

      addLog(`一括仕入れ: 全材料を上限まで補充しました (-¥${totalCost.toLocaleString()})`);
      return { ...prev, money: prev.money - totalCost, ingredients: newIngredients };
    });
  };

  const updateLimit = (type: IngredientType, delta: number) => {
    setGameState(prev => ({
      ...prev,
      ingredientLimits: {
        ...prev.ingredientLimits,
        [type]: Math.max(0, prev.ingredientLimits[type] + delta)
      }
    }));
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({ ...prev, money: prev.money - cost, upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 } }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const handleLevelUp = () => {
    setGameState(prev => {
      const nextLevel = prev.shopLevel + 1;
      const bonusMoney = nextLevel * 50000;
      addLog(`RANK UP!: お店がランク${nextLevel}になりました！ お祝い金 ¥${bonusMoney.toLocaleString()} 獲得！`);

      // Fully restock all ingredients as a reward
      const restockedIngredients = { ...prev.ingredients };
      Object.keys(prev.ingredients).forEach(key => {
        const ingType = key as IngredientType;
        restockedIngredients[ingType] = prev.ingredientLimits[ingType];
      });
      addLog(`ランクアップ特典: 全材料を上限まで補充しました！`);

      return {
        ...prev,
        shopLevel: nextLevel,
        levelProgressSales: 0,
        money: prev.money + bonusMoney,
        ingredients: restockedIngredients
      };
    });
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) { canBake = false; return prev; }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false; return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) { newIngredients[ingKey as IngredientType] -= (amount || 0); }
      return { ...prev, ingredients: newIngredients, bakingStatus: { ...prev.bakingStatus, [breadType]: 0 } };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      if (gameState.upgrades.staff <= 0) return;
      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      const availableStaff: number = (gameState.upgrades.staff as number) - currentBakingCount;
      if (availableStaff <= 0) return;
      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && gameState.inventory[type] < 5 && gameState.bakingStatus[type] === null;
      });
      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;
        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;
            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount; bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else { nextBakingStatus[breadType] = newProgress; }
            changed = true;
          }
        });
        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;
            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions; totalReward += reward; if (allBonus) finalAllBonus = true;
            }
            return { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory, currentMissions: nextMissions, money: prev.money + totalReward, allMissionsBonusClaimed: finalAllBonus };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let totalProgressGained = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];

        // Base progress multiplier
        const brandMultiplier = 1 + (prev.upgrades.brand * 0.2);
        const reputationBonus = 1 + (prev.reputation / 1000); // Max ~1.1x at 100 rep

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) { sellChance *= dailyEvent.salesModifier; if (dailyEvent.trend === breadToSell) sellChance *= 1.5; }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);

                // Calculate level progress bonus
                const isTrend = dailyEvent?.trend === breadToSell;
                const progressForThisSale = (isTrend ? 2 : 1) * brandMultiplier * reputationBonus;

                moneyEarned += price;
                totalProgressGained += progressForThisSale;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;

                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }
        if (moneyEarned === 0) return prev;
        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);
        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions; totalReward += result.reward; if (result.allBonus) allBonus = true;
        });
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return { 
          ...prev, 
          money: prev.money + moneyEarned + totalReward, 
          dailyEarnings: nextDailyEarnings, 
          reputation: prev.reputation + 0.1, 
          levelProgressSales: prev.levelProgressSales + totalProgressGained, 
          inventory: currentInventory, 
          currentMissions: nextMissions, 
          allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus 
        };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0, money: prev.money - wages }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };
  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const totalBrandMultiplier = (1 + (gameState.upgrades.brand * 0.2)).toFixed(1);

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}
      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg text-nowrap">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800 text-sm">{recipe.name}</h3>
                                <div className="bg-amber-100 px-2 py-0.5 rounded text-[10px] font-bold text-amber-700">在庫: {gameState.inventory[recipe.id]}</div>
                            </div>
                            <div className="flex flex-wrap gap-1 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[9px] px-1.5 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden"><div className="bg-amber-500 h-full relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg text-xs shadow-sm">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />ショーケース（在庫状況）</h2>
                <div className="grid grid-cols-2 gap-3 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                  {Object.entries(gameState.inventory).map(([type, count]) => {
                    if (count <= 0) return null;
                    const bread = RECIPES[type as BreadType];
                    return (
                      <div key={type} className="bg-orange-50 border border-orange-100 rounded-xl p-3 flex flex-col items-center text-center transition-all hover:shadow-md">
                        <span className="text-[10px] font-bold text-orange-800 mb-1 leading-tight">{bread.name}</span>
                        <div className="flex items-baseline gap-1">
                          <span className="text-lg font-bold text-orange-900">{count}</span>
                          <span className="text-[10px] text-orange-600">個</span>
                        </div>
                      </div>
                    );
                  })}
                  {Object.values(gameState.inventory).every(c => c === 0) && (
                    <div className="col-span-2 py-8 text-center text-stone-400 text-xs italic">
                      現在、在庫はありません。<br/>パンを焼きましょう！
                    </div>
                  )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 relative">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 目標</h2>
                  <div className="flex items-center gap-1 bg-amber-50 border border-amber-200 px-2 py-0.5 rounded-full">
                    <Icons.Zap className="w-3 h-3 text-amber-500" />
                    <span className="text-[9px] font-bold text-amber-700">進捗 x{totalBrandMultiplier}</span>
                  </div>
                </div>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-[10px] font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-3 h-3 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1 overflow-hidden">
                                <div className={`h-full ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-[10px] font-bold text-amber-800">RANK: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">進捗: {Math.floor(gameState.levelProgressSales)} / {getLevelUpThreshold(gameState.shopLevel)} pt</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-2"><div className="bg-orange-500 h-full rounded-full transition-all duration-500 shadow-[0_0_5px_rgba(249,115,22,0.5)]" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={handleLevelUp} className="w-full py-1.5 bg-orange-500 text-white text-[10px] font-bold rounded shadow-lg animate-bounce">ランクアップ可能！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl text-xs border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 text-sm transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                  <button onClick={restockAllToLimit} className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold px-2 py-1 rounded-lg border border-amber-200 transition-colors">
                    上限まで一括仕入れ
                  </button>
                </div>
                <div className="space-y-3 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const current = gameState.ingredients[item.id];
                        const limit = gameState.ingredientLimits[item.id];
                        const progress = Math.min(100, (current / limit) * 100);
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        const isFull = current >= limit;

                        return (
                            <div key={item.id} className="p-3 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="flex items-center gap-2">
                                      <div className="font-bold text-stone-700 text-xs">{item.name}</div>
                                      <div className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${isFull ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {current} / {limit}{item.unit}
                                      </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                      <button onClick={() => updateLimit(item.id, -50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">-</button>
                                      <div className="text-[9px] font-bold text-stone-400">上限</div>
                                      <button onClick={() => updateLimit(item.id, 50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">+</button>
                                    </div>
                                </div>
                                <div className="w-full bg-stone-200 h-1 rounded-full overflow-hidden mb-2">
                                  <div className={`h-full transition-all duration-500 ${isFull ? 'bg-orange-500' : 'bg-blue-500'}`} style={{ width: `${progress}%` }}></div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button 
                                          key={amount} 
                                          onClick={() => buyIngredient(item.id, amount)} 
                                          disabled={isFull || gameState.money < (unitCost * amount)} 
                                          className={`py-1 rounded text-[9px] font-bold flex flex-col items-center border transition-all 
                                            ${!isFull && gameState.money >= (unitCost * amount) 
                                              ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' 
                                              : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}`}
                                        >
                                            <span className="opacity-60">x{amount}</span>
                                            <span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './components/Icon';
import { DailyModal } from './components/DailyModal';
import { InventoryItem } from './components/InventoryItem';
import { UpgradeModal } from './components/UpgradeModal';
import { Bakery3DScene } from './components/Bakery3DScene';
import { generateDailyReport } from './services/geminiService';
import { 
  GameState, 
  IngredientType, 
  BreadType, 
  DailyEvent,
  UpgradeStats,
  DailyMission
} from './types';
import { INGREDIENTS_DATA, RECIPES, INITIAL_MONEY, getLevelUpThreshold, DAILY_WAGE_PER_STAFF, UPGRADES_DATA } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    money: INITIAL_MONEY,
    day: 1,
    dailyEarnings: 0,
    reputation: 10,
    shopLevel: 1,
    levelProgressSales: 0,
    ingredients: {
      [IngredientType.FLOUR]: 100, [IngredientType.SUGAR]: 100, [IngredientType.BUTTER]: 100,
      [IngredientType.YEAST]: 100, [IngredientType.MILK]: 100, [IngredientType.EGGS]: 100,
      [IngredientType.SALT]: 100, [IngredientType.CHOCO]: 100, [IngredientType.ANKO]: 100,
      [IngredientType.CURRY]: 100, [IngredientType.VEGETABLES]: 100, [IngredientType.MEAT]: 100,
      [IngredientType.FISH]: 100,
    },
    ingredientLimits: {
      [IngredientType.FLOUR]: 200, [IngredientType.SUGAR]: 200, [IngredientType.BUTTER]: 200,
      [IngredientType.YEAST]: 200, [IngredientType.MILK]: 200, [IngredientType.EGGS]: 200,
      [IngredientType.SALT]: 200, [IngredientType.CHOCO]: 200, [IngredientType.ANKO]: 200,
      [IngredientType.CURRY]: 200, [IngredientType.VEGETABLES]: 200, [IngredientType.MEAT]: 200,
      [IngredientType.FISH]: 200,
    },
    inventory: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: 0 }), {} as Record<BreadType, number>),
    isShopOpen: false,
    bakingStatus: Object.values(BreadType).reduce((acc, type) => ({ ...acc, [type]: null }), {} as Record<BreadType, number | null>),
    upgrades: { speed: 0, batch: 0, promo: 0, branches: 1, eatIn: 0, staff: 0, brand: 0 },
    currentMissions: [],
    allMissionsBonusClaimed: false
  });

  const [dailyEvent, setDailyEvent] = useState<DailyEvent | null>(null);
  const [loadingDaily, setLoadingDaily] = useState(false);
  const [showUpgrades, setShowUpgrades] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [lastSale, setLastSale] = useState<{ id: number; bread: BreadType; timestamp: number } | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 50));

  const processMissionUpdates = (prevMissions: DailyMission[], type: DailyMission['type'], targetId: string | undefined, increment: number, currentDailyEarnings: number): { missions: DailyMission[], reward: number, allBonus: boolean } => {
    let extraMoney = 0;
    const nextMissions = prevMissions.map(mission => {
      if (mission.isCleared) return mission;
      let nextVal = mission.type === 'earn_money' ? currentDailyEarnings : (mission.type === type && (!mission.targetId || mission.targetId === targetId) ? mission.currentValue + increment : mission.currentValue);
      const isNowCleared = nextVal >= mission.targetValue;
      if (isNowCleared && !mission.isCleared) {
        extraMoney += 50000;
        addLog(`ミッション達成: ${mission.description} (報酬: ¥50,000)`);
      }
      return { ...mission, currentValue: nextVal, isCleared: isNowCleared };
    });
    let allBonus = nextMissions.length > 0 && nextMissions.every(m => m.isCleared) && !nextMissions.every((m, i) => prevMissions[i].isCleared);
    if (allBonus) {
        addLog(`全ミッション達成ボーナス！ (報酬: ¥150,000)`);
        extraMoney += 150000;
    }
    return { missions: nextMissions, reward: extraMoney, allBonus };
  };

  const buyIngredient = (type: IngredientType, amount: number = 1) => {
    const item = INGREDIENTS_DATA[type];
    const costModifier = dailyEvent?.costModifier || 1.0;
    const unitCost = Math.floor(item.cost * costModifier);

    setGameState(prev => {
      const currentStock = prev.ingredients[type];
      const limit = prev.ingredientLimits[type];
      const possibleAmount = Math.min(amount, limit - currentStock);

      if (possibleAmount <= 0) {
        addLog(`仕入れ不可: ${item.name} は在庫上限 (${limit}${item.unit}) に達しています`);
        return prev;
      }

      const totalCost = unitCost * possibleAmount;
      if (prev.money < totalCost) {
        addLog(`資金不足: ${item.name} ${possibleAmount}個 分の資金が足りません`);
        return prev;
      }

      const { missions, reward, allBonus } = processMissionUpdates(prev.currentMissions, 'buy_ingredient', type, possibleAmount, prev.dailyEarnings);
      addLog(`仕入れ: ${item.name} を${possibleAmount}${item.unit}購入しました (-¥${totalCost.toLocaleString()})`);
      return {
        ...prev,
        money: prev.money - totalCost + reward,
        ingredients: { ...prev.ingredients, [type]: currentStock + possibleAmount },
        currentMissions: missions,
        allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus
      };
    });
  };

  const restockAllToLimit = () => {
    setGameState(prev => {
      let totalCost = 0;
      const newIngredients = { ...prev.ingredients };
      const costModifier = dailyEvent?.costModifier || 1.0;
      let purchasedCount = 0;

      Object.values(IngredientType).forEach(type => {
        const item = INGREDIENTS_DATA[type];
        const limit = prev.ingredientLimits[type];
        const current = prev.ingredients[type];
        const need = Math.max(0, limit - current);
        if (need > 0) {
          const cost = Math.floor(item.cost * costModifier) * need;
          if (prev.money >= totalCost + cost) {
            totalCost += cost;
            newIngredients[type] += need;
            purchasedCount++;
          }
        }
      });

      if (purchasedCount === 0) {
        addLog("一括仕入れ: 補充が必要な材料がないか、資金が足りません");
        return prev;
      }

      addLog(`一括仕入れ: 全材料を上限まで補充しました (-¥${totalCost.toLocaleString()})`);
      return { ...prev, money: prev.money - totalCost, ingredients: newIngredients };
    });
  };

  const updateLimit = (type: IngredientType, delta: number) => {
    setGameState(prev => ({
      ...prev,
      ingredientLimits: {
        ...prev.ingredientLimits,
        [type]: Math.max(0, prev.ingredientLimits[type] + delta)
      }
    }));
  };

  const buyUpgrade = (key: keyof UpgradeStats, cost: number) => {
    if (gameState.money >= cost) {
      setGameState(prev => ({ ...prev, money: prev.money - cost, upgrades: { ...prev.upgrades, [key]: prev.upgrades[key] + 1 } }));
      addLog(`設備投資: ${UPGRADES_DATA[key].name} を購入しました (-¥${cost.toLocaleString()})`);
    }
  };

  const handleLevelUp = () => {
    setGameState(prev => {
      const nextLevel = prev.shopLevel + 1;
      const bonusMoney = nextLevel * 50000;
      addLog(`RANK UP!: お店がランク${nextLevel}になりました！ お祝い金 ¥${bonusMoney.toLocaleString()} 獲得！`);

      // Fully restock all ingredients as a reward
      const restockedIngredients = { ...prev.ingredients };
      Object.keys(prev.ingredients).forEach(key => {
        const ingType = key as IngredientType;
        restockedIngredients[ingType] = prev.ingredientLimits[ingType];
      });
      addLog(`ランクアップ特典: 全材料を上限まで補充しました！`);

      return {
        ...prev,
        shopLevel: nextLevel,
        levelProgressSales: 0,
        money: prev.money + bonusMoney,
        ingredients: restockedIngredients
      };
    });
  };

  const startBaking = (breadType: BreadType, isAuto = false) => {
    let canBake = true;
    setGameState(prev => {
      if (prev.bakingStatus[breadType] !== null) { canBake = false; return prev; }
      const recipe = RECIPES[breadType];
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) {
          const key = ingKey as IngredientType;
          if ((prev.ingredients[key] || 0) < (amount || 0)) {
              if (!isAuto) addLog(`材料不足: ${recipe.name} 用の ${INGREDIENTS_DATA[key].name} が足りません`);
              canBake = false; return prev;
          }
      }
      const newIngredients = { ...prev.ingredients };
      for (const [ingKey, amount] of Object.entries(recipe.ingredients)) { newIngredients[ingKey as IngredientType] -= (amount || 0); }
      return { ...prev, ingredients: newIngredients, bakingStatus: { ...prev.bakingStatus, [breadType]: 0 } };
    });
    if (canBake) addLog(`${isAuto ? 'スタッフ代行' : '調理開始'}: ${RECIPES[breadType].name} を焼き始めました`);
    return canBake;
  };

  useEffect(() => {
    const automationInterval = setInterval(() => {
      // FIX: Explicitly cast to number to ensure 'staff' value is not treated as unknown
      const staffVal = gameState.upgrades.staff as number;
      if (staffVal <= 0) return;

      const currentBakingCount = Object.values(gameState.bakingStatus).filter(s => s !== null).length;
      // FIX: Ensure availableStaff is calculated and checked as a number
      const availableStaff = staffVal - currentBakingCount;
      if (availableStaff <= 0) return;

      const lowStockBreads = Object.values(BreadType).filter(type => {
        const recipe = RECIPES[type];
        return recipe.levelRequired <= gameState.shopLevel && gameState.inventory[type] < 5 && gameState.bakingStatus[type] === null;
      });
      lowStockBreads.slice(0, availableStaff).forEach(breadType => startBaking(breadType, true));
    }, 2000);
    return () => clearInterval(automationInterval);
  }, [gameState.upgrades.staff, gameState.inventory, gameState.bakingStatus, gameState.shopLevel]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGameState(prev => {
        const nextBakingStatus = { ...prev.bakingStatus };
        const nextInventory = { ...prev.inventory };
        let bakedType: BreadType | null = null;
        let bakedCount = 0;
        let changed = false;
        Object.keys(nextBakingStatus).forEach((key) => {
          const breadType = key as BreadType;
          const progress = nextBakingStatus[breadType];
          if (progress !== null) {
            const recipe = RECIPES[breadType];
            const speedMultiplier = Math.pow(0.95, prev.upgrades.speed);
            const increment = 100 / (Math.max(0.1, recipe.bakeTimeSec * speedMultiplier) * 10);
            const newProgress = progress + increment;
            if (newProgress >= 100) {
              nextBakingStatus[breadType] = null;
              const totalAmount = recipe.batchSize + prev.upgrades.batch;
              nextInventory[breadType] += totalAmount;
              bakedCount = totalAmount; bakedType = breadType;
              addLog(`焼き上がり: ${recipe.name} が ${totalAmount}個 完成！`);
            } else { nextBakingStatus[breadType] = newProgress; }
            changed = true;
          }
        });
        if (changed) {
            let nextMissions = prev.currentMissions;
            let totalReward = 0;
            let finalAllBonus = prev.allMissionsBonusClaimed;
            if (bakedType) {
                const { missions, reward, allBonus } = processMissionUpdates(nextMissions, 'bake_bread', bakedType, bakedCount, prev.dailyEarnings);
                nextMissions = missions; totalReward += reward; if (allBonus) finalAllBonus = true;
            }
            return { ...prev, bakingStatus: nextBakingStatus, inventory: nextInventory, currentMissions: nextMissions, money: prev.money + totalReward, allMissionsBonusClaimed: finalAllBonus };
        }
        return prev;
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!gameState.isShopOpen) return;
    const sellInterval = setInterval(() => {
      setGameState(prev => {
        const numBranches = prev.upgrades.branches;
        let moneyEarned = 0;
        let totalProgressGained = 0;
        let lastSoldBread: BreadType | null = null;
        const currentInventory = { ...prev.inventory };
        const soldHistory: {type: BreadType, count: number}[] = [];

        // Base progress multiplier
        const brandMultiplier = 1 + (prev.upgrades.brand * 0.2);
        const reputationBonus = 1 + (prev.reputation / 1000); // Max ~1.1x at 100 rep

        for (let i = 0; i < numBranches; i++) {
            const availableBreads = (Object.keys(currentInventory) as BreadType[]).filter(k => currentInventory[k] > 0);
            if (availableBreads.length === 0) continue; 
            const breadToSell = availableBreads[Math.floor(Math.random() * availableBreads.length)];
            const recipe = RECIPES[breadToSell];
            let sellChance = (0.3 + (prev.reputation / 200)) * (1 + (prev.upgrades.promo * 0.05));
            if (dailyEvent) { sellChance *= dailyEvent.salesModifier; if (dailyEvent.trend === breadToSell) sellChance *= 1.5; }

            if (Math.random() < sellChance) {
                let price = recipe.basePrice;
                if (Math.random() < Math.min(0.8, prev.upgrades.eatIn * 0.02)) price = Math.floor(price * 1.5);

                // Calculate level progress bonus
                const isTrend = dailyEvent?.trend === breadToSell;
                const progressForThisSale = (isTrend ? 2 : 1) * brandMultiplier * reputationBonus;

                moneyEarned += price;
                totalProgressGained += progressForThisSale;
                currentInventory[breadToSell] -= 1;
                lastSoldBread = breadToSell;

                const existing = soldHistory.find(sb => sb.type === breadToSell);
                if (existing) existing.count++; else soldHistory.push({type: breadToSell, count: 1});
            }
        }
        if (moneyEarned === 0) return prev;
        const nextDailyEarnings = prev.dailyEarnings + moneyEarned;
        let { missions: nextMissions, reward: totalReward, allBonus } = processMissionUpdates(prev.currentMissions, 'earn_money', undefined, 0, nextDailyEarnings);
        soldHistory.forEach(sh => {
            const result = processMissionUpdates(nextMissions, 'sell_bread', sh.type, sh.count, nextDailyEarnings);
            nextMissions = result.missions; totalReward += result.reward; if (result.allBonus) allBonus = true;
        });
        if (lastSoldBread) setLastSale({ id: Date.now() + Math.random(), bread: lastSoldBread, timestamp: Date.now() });
        return { 
          ...prev, 
          money: prev.money + moneyEarned + totalReward, 
          dailyEarnings: nextDailyEarnings, 
          reputation: prev.reputation + 0.1, 
          levelProgressSales: prev.levelProgressSales + totalProgressGained, 
          inventory: currentInventory, 
          currentMissions: nextMissions, 
          allMissionsBonusClaimed: prev.allMissionsBonusClaimed || allBonus 
        };
      });
    }, 1000); 
    return () => clearInterval(sellInterval);
  }, [gameState.isShopOpen, dailyEvent]);

  const prepareDay = async (targetDay: number) => {
    setLoadingDaily(true);
    const wages = gameState.upgrades.staff * DAILY_WAGE_PER_STAFF;
    if (wages > 0) addLog(`経費支払い: アルバイト ${gameState.upgrades.staff}人分の給与 ¥${wages.toLocaleString()} を支払いました`);
    setGameState(prev => ({ ...prev, isShopOpen: false, allMissionsBonusClaimed: false, dailyEarnings: 0, money: prev.money - wages }));
    const report = await generateDailyReport(targetDay, gameState.shopLevel);
    setDailyEvent(report);
    setGameState(prev => ({ ...prev, day: targetDay, currentMissions: report.missions }));
    setLoadingDaily(false);
  };

  const startNextDay = () => prepareDay(gameState.day + 1);
  const openShop = () => { setGameState(prev => ({ ...prev, isShopOpen: true })); setDailyEvent(null); addLog("開店: お店をオープンしました！"); };
  const closeShopEarly = () => { setGameState(prev => ({ ...prev, isShopOpen: false })); addLog("閉店: 本日の営業を終了しました。"); };
  useEffect(() => { if (gameState.day === 1 && !dailyEvent && !gameState.isShopOpen) prepareDay(1); }, []);

  const progressPercent = Math.min(100, (gameState.levelProgressSales / getLevelUpThreshold(gameState.shopLevel)) * 100);
  const totalBrandMultiplier = (1 + (gameState.upgrades.brand * 0.2)).toFixed(1);

  const cameras = [
    { name: "CAM 01: FRONT", pos: [0, 5, 8] as [number, number, number], fov: 45 },
    { name: "CAM 02: SIDE", pos: [8, 4, 3] as [number, number, number], fov: 50 },
    { name: "CAM 03: TOP", pos: [0, 12, 1] as [number, number, number], fov: 40 },
    { name: "CAM 04: EAT-IN", pos: [-6, 6, 8] as [number, number, number], fov: 55 },
  ];

  return (
    <div className="min-h-screen pb-12 bg-[#fdf6e3]">
      {loadingDaily && (
        <div className="fixed inset-0 z-50 bg-[#fdf6e3] flex flex-col items-center justify-center">
            <Icons.Wheat className="w-16 h-16 text-amber-500 animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-amber-800 text-center">朝の準備中...<br/><span className="text-sm font-normal text-amber-600">トレンドを分析しています</span></h2>
        </div>
      )}
      {dailyEvent && !loadingDaily && <DailyModal event={dailyEvent} onClose={openShop} />}
      {showUpgrades && <UpgradeModal currentMoney={gameState.money} upgrades={gameState.upgrades} onBuy={buyUpgrade} onClose={() => setShowUpgrades(false)} />}

      <header className="sticky top-0 z-10 bg-white/90 backdrop-blur-md border-b border-amber-200 shadow-sm px-4 py-3">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
            <div className="flex items-center gap-2">
                <div className="bg-amber-500 p-2 rounded-lg text-white shadow-sm"><Icons.Store className="w-5 h-5 sm:w-6 sm:h-6" /></div>
                <div><h1 className="font-bold text-amber-900 leading-tight text-xs sm:text-lg text-nowrap">小麦の詩</h1></div>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
                <div className="bg-amber-100 px-3 py-1 rounded-full text-amber-800 text-[10px] sm:text-xs font-bold tracking-wider">{gameState.day}日目</div>
                <div className="flex flex-col items-end">
                    <div className="text-amber-800 text-xs sm:text-sm font-bold">¥{gameState.money.toLocaleString()}</div>
                </div>
                <button onClick={() => setShowUpgrades(true)} className="bg-amber-500 hover:bg-amber-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-lg transition-all active:scale-90"><Icons.Hammer className="w-4 h-4" /></button>
            </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ChefHat className="w-5 h-5 text-amber-600" />工房</h2>
                <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(RECIPES).filter(r => r.levelRequired <= gameState.shopLevel).map(recipe => (
                        <div key={recipe.id} className="border border-stone-200 rounded-xl p-4 bg-stone-50 hover:border-amber-200 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-stone-800 text-sm">{recipe.name}</h3>
                                <div className="bg-amber-100 px-2 py-0.5 rounded text-[10px] font-bold text-amber-700">在庫: {gameState.inventory[recipe.id]}</div>
                            </div>
                            <div className="flex flex-wrap gap-1 mb-3">
                                {Object.entries(recipe.ingredients).map(([ing, amount]) => (
                                    <span key={ing} className={`text-[9px] px-1.5 py-0.5 rounded ${gameState.ingredients[ing as IngredientType] < (amount || 0) ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                                        {INGREDIENTS_DATA[ing as IngredientType].name} x{amount}
                                    </span>
                                ))}
                            </div>
                            {gameState.bakingStatus[recipe.id] !== null ? (
                                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden"><div className="bg-amber-500 h-full relative" style={{ width: `${gameState.bakingStatus[recipe.id]}%` }}><div className="absolute inset-0 bg-white/20 animate-pulse"></div></div></div>
                            ) : (
                                <button onClick={() => startBaking(recipe.id)} className="w-full py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg text-xs shadow-sm">パンを焼く</button>
                            )}
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <h2 className="text-lg font-bold text-amber-900 mb-4 flex items-center gap-2"><Icons.ShoppingBag className="w-5 h-5 text-amber-600" />ショーケース（在庫状況）</h2>
                <div className="grid grid-cols-2 gap-3 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                  {Object.entries(gameState.inventory).map(([type, count]) => {
                    if (count <= 0) return null;
                    const bread = RECIPES[type as BreadType];
                    return (
                      <div key={type} className="bg-orange-50 border border-orange-100 rounded-xl p-3 flex flex-col items-center text-center transition-all hover:shadow-md">
                        <span className="text-[10px] font-bold text-orange-800 mb-1 leading-tight">{bread.name}</span>
                        <div className="flex items-baseline gap-1">
                          <span className="text-lg font-bold text-orange-900">{count}</span>
                          <span className="text-[10px] text-orange-600">個</span>
                        </div>
                      </div>
                    );
                  })}
                  {Object.values(gameState.inventory).every(c => c === 0) && (
                    <div className="col-span-2 py-8 text-center text-stone-400 text-xs italic">
                      現在、在庫はありません。<br/>パンを焼きましょう！
                    </div>
                  )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-stone-900 rounded-2xl shadow-2xl border-4 border-stone-800 p-1">
                <div className="grid grid-cols-2 gap-1 overflow-hidden rounded-xl">
                    {cameras.map((cam, idx) => (
                        <div key={idx} className="relative h-40 md:h-48 bg-black border border-stone-800 overflow-hidden">
                            <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5 pointer-events-none">
                                <span className="bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded font-mono uppercase tracking-tighter">{cam.name}</span>
                                {gameState.isShopOpen && <div className="flex items-center gap-1 bg-red-600/40 px-1.5 py-0.5 rounded"><div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div><span className="text-white text-[7px] font-bold font-mono">LIVE</span></div>}
                            </div>
                            <Bakery3DScene lastSale={lastSale} inventory={gameState.inventory} eatInLevel={gameState.upgrades.eatIn} staffCount={gameState.upgrades.staff} cameraPosition={cam.pos} cameraFov={cam.fov}/>
                        </div>
                    ))}
                </div>
            </section>

            <section className="bg-white rounded-2xl shadow-sm border border-amber-200 p-5 relative">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.TrendingUp className="w-5 h-5 text-amber-600" /> 目標</h2>
                  <div className="flex items-center gap-1 bg-amber-50 border border-amber-200 px-2 py-0.5 rounded-full">
                    <Icons.Zap className="w-3 h-3 text-amber-500" />
                    <span className="text-[9px] font-bold text-amber-700">進捗 x{totalBrandMultiplier}</span>
                  </div>
                </div>
                <div className="space-y-3">
                    {gameState.currentMissions.map(m => (
                        <div key={m.id} className={`p-3 rounded-xl border transition-all ${m.isCleared ? 'bg-green-50 border-green-200' : 'bg-stone-50 border-stone-100'}`}>
                            <div className="flex justify-between items-center mb-1">
                                <span className={`text-[10px] font-bold ${m.isCleared ? 'text-green-700' : 'text-stone-700'}`}>{m.description}</span>
                                {m.isCleared && <Icons.Zap className="w-3 h-3 text-green-500 fill-green-500" />}
                            </div>
                            <div className="w-full bg-stone-200 rounded-full h-1 overflow-hidden">
                                <div className={`h-full ${m.isCleared ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${Math.min(100, (m.currentValue / m.targetValue) * 100)}%` }}></div>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="mt-4 pt-4 border-t border-amber-100">
                    <div className="flex justify-between items-center mb-1"><h3 className="text-[10px] font-bold text-amber-800">RANK: {gameState.shopLevel}</h3><span className="text-[10px] text-stone-400">進捗: {Math.floor(gameState.levelProgressSales)} / {getLevelUpThreshold(gameState.shopLevel)} pt</span></div>
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-2"><div className="bg-orange-500 h-full rounded-full transition-all duration-500 shadow-[0_0_5px_rgba(249,115,22,0.5)]" style={{ width: `${progressPercent}%` }}></div></div>
                    {gameState.levelProgressSales >= getLevelUpThreshold(gameState.shopLevel) && (
                        <button onClick={handleLevelUp} className="w-full py-1.5 bg-orange-500 text-white text-[10px] font-bold rounded shadow-lg animate-bounce">ランクアップ可能！</button>
                    )}
                </div>
                <div className="mt-4 flex flex-col gap-2">
                    {gameState.isShopOpen ? (
                        <button onClick={closeShopEarly} className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 font-bold rounded-xl text-xs border border-red-200">営業終了</button>
                    ) : (
                        <button onClick={startNextDay} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg flex items-center justify-center gap-2 text-sm transition-all active:scale-95">翌日の準備へ <Icons.Sun className="w-4 h-4" /></button>
                    )}
                </div>
            </section>
        </div>

        <div className="space-y-6">
            <section className="bg-white rounded-2xl shadow-sm border border-amber-100 p-5">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2"><Icons.Store className="w-5 h-5 text-amber-600" />パントリー</h2>
                  <button onClick={restockAllToLimit} className="text-[10px] bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold px-2 py-1 rounded-lg border border-amber-200 transition-colors">
                    上限まで一括仕入れ
                  </button>
                </div>
                <div className="space-y-3 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    {Object.values(INGREDIENTS_DATA).map(item => {
                        const current = gameState.ingredients[item.id];
                        const limit = gameState.ingredientLimits[item.id];
                        const progress = Math.min(100, (current / limit) * 100);
                        const unitCost = Math.floor(item.cost * (dailyEvent?.costModifier || 1.0));
                        const isFull = current >= limit;

                        return (
                            <div key={item.id} className="p-3 border border-stone-100 rounded-xl bg-stone-50/50">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="flex items-center gap-2">
                                      <div className="font-bold text-stone-700 text-xs">{item.name}</div>
                                      <div className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold ${isFull ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                        {current} / {limit}{item.unit}
                                      </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                      <button onClick={() => updateLimit(item.id, -50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">-</button>
                                      <div className="text-[9px] font-bold text-stone-400">上限</div>
                                      <button onClick={() => updateLimit(item.id, 50)} className="w-5 h-5 bg-white border border-stone-200 text-[10px] flex items-center justify-center rounded text-stone-500 hover:bg-stone-100">+</button>
                                    </div>
                                </div>
                                <div className="w-full bg-stone-200 h-1 rounded-full overflow-hidden mb-2">
                                  <div className={`h-full transition-all duration-500 ${isFull ? 'bg-orange-500' : 'bg-blue-500'}`} style={{ width: `${progress}%` }}></div>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {[1, 10, 50].map(amount => (
                                        <button 
                                          key={amount} 
                                          onClick={() => buyIngredient(item.id, amount)} 
                                          disabled={isFull || gameState.money < (unitCost * amount)} 
                                          className={`py-1 rounded text-[9px] font-bold flex flex-col items-center border transition-all 
                                            ${!isFull && gameState.money >= (unitCost * amount) 
                                              ? 'bg-white text-stone-700 border-stone-200 hover:bg-amber-50 active:scale-95' 
                                              : 'bg-gray-50 text-gray-300 border-gray-100 cursor-not-allowed'}`}
                                        >
                                            <span className="opacity-60">x{amount}</span>
                                            <span>¥{(unitCost * amount).toLocaleString()}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
      </main>
    </div>
  );
};

export default App;
